/* Source: user-supplied 2025–2026 exam papers and official answer sheets. */
(()=>{'use strict';const data={"version":"2026-10-28.3","exams":[{"id":"2025-1-03","year":2025,"grade":1,"month":3,"count":20},{"id":"2025-1-06","year":2025,"grade":1,"month":6,"count":25},{"id":"2025-1-09","year":2025,"grade":1,"month":9,"count":25},{"id":"2025-1-10","year":2025,"grade":1,"month":10,"count":25},{"id":"2026-1-03","year":2026,"grade":1,"month":3,"count":25},{"id":"2026-1-06","year":2026,"grade":1,"month":6,"count":25},{"id":"2026-1-09","year":2026,"grade":1,"month":9,"count":25},{"id":"2026-1-10","year":2026,"grade":1,"month":10,"count":25},{"id":"2026-2-03","year":2026,"grade":2,"month":3,"count":25},{"id":"2026-2-06","year":2026,"grade":2,"month":6,"count":25},{"id":"2026-2-09","year":2026,"grade":2,"month":9,"count":25},{"id":"2026-2-10","year":2026,"grade":2,"month":10,"count":25}],"questions":[{"id":"2025-1-06-11","year":2025,"grade":1,"month":6,"number":11,"modules":["ripple"],"image":"assets/exams/2025-1-06-11.jpg","pdfPage":3,"topic":"정부·기업의 환경 관련 역할","level":2,"points":2,"prompt":"다음 자료에 대한 설명으로 옳은 것은?","body":"<p>A~C는 각각 기업·정부·시민 단체 중 하나이다.</p><div class=\"ep-passage\"><div class=\"ep-material\"><strong>A</strong><p>미세플라스틱이 인체에 심각한 위협이 됨을 알리고, <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">건강하고 쾌적한 환경에서 생활할 권리</u> 보장을 위한 대책을 촉구하는 집회를 열었다.</p></div><div class=\"ep-material\"><strong>B</strong><p>미세플라스틱 배출에 따른 해양 오염의 심각성을 인지하고, 전문가들과 공식 공청회를 열어 <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">이와 관련한 규제 정책의 보완</u>에 나섰다.</p></div><div class=\"ep-material\"><strong>C</strong><p>오염 문제를 개선하기 위해 친환경 경영을 선언하고 생분해성 플라스틱 소재의 개발과 생산에 나섰다.</p></div></div>","options":["㉠은 헌법에서 보장되지 않는다.","㉡으로는 폐수 처리 기준의 완화를 들 수 있다.","B는 국제 협약을 맺어 국제 사회와 협력할 수 있다.","B와 달리 C는 환경 오염 행위를 감시하고 법적 제재를 가할 수 있다.","C와 달리 A는 기술 혁신을 통해 오염 물질 배출을 줄일 수 있다."],"correct":2,"summary":"규제 정책을 정비하는 B는 정부예요. 정부는 국제 협약을 맺고 다른 국가와 함께 환경 문제 해결에 참여할 수 있어요.","steps":[{"title":"행동에서 주체를 찾아요","text":"집회·시민의 요구를 전달하는 A는 시민 단체, 규제 정책을 보완하는 B는 정부, 기술 개발·생산을 하는 C는 기업이에요."},{"title":"법적 권한과 생산 활동을 구분해요","text":"정부는 규제와 법적 제재를 담당할 수 있어요. 기업은 친환경 소재·기술을 개발하고 제품을 생산할 수 있어요."},{"title":"환경 맥락의 연결 개념을 확인해요","text":"㉠은 환경권으로 헌법상 보장되는 권리예요. 오염을 줄이려면 폐수 처리 기준의 완화보다 강화가 적절해요."}],"reasons":["건강하고 쾌적한 환경에서 생활할 환경권은 헌법상 보장되는 권리예요.","처리 기준을 완화하면 오염 억제가 약해질 수 있어요. 오염 문제 해결을 위한 강화 방향과 구분해요.","정부 B는 국제 협약을 맺어 국제 사회와 협력할 수 있어요.","법적 제재를 가할 수 있는 주체는 정부 B예요. C 기업과 구분해요.","친환경 소재 개발 등 기술 혁신을 통한 생산은 기업 C의 역할이에요."],"linked":true},{"id":"2025-1-10-14","year":2025,"grade":1,"month":10,"number":14,"modules":["capitalism"],"image":"assets/exams/2025-1-10-14.jpg","pdfPage":4,"topic":"수정 자본주의·신자유주의","level":2,"points":2,"prompt":"갑과 을의 주장에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-material\"><strong>갑</strong><p>대공황으로 인한 대규모 실업 문제를 해결하기 위해서는 정부가 시장에 적극 개입해야 합니다. 정부는 공공사업을 펼쳐 일자리를 창출하고 구매력을 늘려 경제를 활성화시켜야 합니다.</p></div><div class=\"ep-material\"><strong>을</strong><p>대공황이 발생해도 시장의 조절 기능에 따라 시장은 균형을 향해 갈 것이며 정부의 공공사업은 물가 상승을 초래할 뿐입니다. 자유로운 경쟁이 보장되는 시장의 자생적인 질서를 존중해야 합니다.</p></div>","options":["갑의 주장은 수정 자본주의와 부합한다.","갑의 주장은 석유 파동에 따른 스태그플레이션을 해결하기 위해 등장하였다.","을의 주장을 토대로 뉴딜 정책이 추진되었다.","을의 주장을 계기로 혼합 경제 체제가 등장하였다.","갑, 을은 모두 복지 정책 축소와 공기업 민영화를 지지한다."],"correct":0,"summary":"공공사업과 정부의 적극적 개입을 강조하는 갑은 케인즈의 입장이에요. 대공황을 해결하려는 수정 자본주의와 연결돼요.","steps":[{"title":"정부 역할에 관한 핵심어를 찾아요","text":"갑의 공공사업·일자리 창출은 정부 개입을 강조해요. 을은 자유 경쟁과 시장의 자생적 질서를 강조해요."},{"title":"등장 배경을 구분해요","text":"수정 자본주의는 대공황과 시장 실패, 신자유주의는 1970년대 석유 파동 이후 정부 개입의 한계와 연결해요."},{"title":"정책을 연결해요","text":"뉴딜 정책은 정부가 공공사업 등으로 경제를 활성화하려는 정책이에요. 복지 축소·공기업 민영화는 을의 입장과 연결돼요."}],"reasons":["정부 개입으로 실업과 수요 부족을 해결하려는 갑의 주장은 수정 자본주의에 해당해요.","갑은 1929년 대공황 해결과 연결돼요. 석유 파동 이후의 신자유주의와 시대를 구분해요.","뉴딜 정책은 갑처럼 정부의 적극적 역할을 강조하는 입장과 연결돼요.","시장 경제에 계획 경제의 요소를 결합한 혼합 경제 체제는 정부 개입을 강조하는 갑과 연결돼요.","복지 축소와 공기업 민영화는 을의 입장에 가까워요. 갑·을 모두의 주장으로 묶을 수 없어요."],"linked":false},{"id":"2025-1-10-17","year":2025,"grade":1,"month":10,"number":17,"modules":["finance"],"image":"assets/exams/2025-1-10-17.jpg","pdfPage":4,"topic":"금융 상품의 수익·경제 상황","level":3,"points":2.5,"prompt":"다음 자료에 대한 분석 및 추론으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>A국 국민 갑은 자산 전부인 5,000달러를 금융 상품에 투자하고 있다.</p><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">금융 상품</th><th scope=\"col\">투자액(달러)</th></tr></thead><tbody><tr><th scope=\"row\">A국 ○○은행 정기 예금</th><td>1,000</td></tr><tr><th scope=\"row\">A국 ◇◇기업 주식</th><td>2,500</td></tr><tr><th scope=\"row\">B국 발행 채권</th><td>1,500</td></tr></tbody></table></div><div class=\"ep-material\"><strong>경제 상황</strong><p>A국 중앙은행은 기준 금리 인상을 결정했다. B국의 장기 내전으로 수입 원자재 가격이 급등하며 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">물가 상승</u>세가 심화된 데 따른 조치다. 금리 인상은 시중 금리 상승과 대출 부담 증가로 이어질 수 있지만, A국 물가 안정에 도움이 될 것이라는 전망이 나왔다.</p></div><p>갑은 이 상황을 고려해 금융 상품별 투자 비중을 조정하려 한다.</p></div>","options":["갑은 배당 수익을 기대할 수 있는 금융 상품에 가장 적은 금액을 투자하고 있다.","갑의 총투자액 중 시세 차익을 기대할 수 있는 금융 상품 투자액의 비율은 80%이다.","㉠은 가계의 소비를 증가시키는 요인이다.","A국의 금리 변동은 갑의 ○○은행 정기 예금 비중의 감소 요인이다.","안전성만 고려한다면 갑은 B국 발행 채권의 투자 비중을 늘리는 것이 합리적이다."],"correct":1,"summary":"시세 차익은 주식과 채권의 가격 변화로 기대할 수 있어요. 두 투자액을 더하면 4,000달러로 전체 5,000달러의 80%예요.","steps":[{"title":"수익 종류를 상품과 연결해요","text":"예금은 이자, 주식은 배당과 시세 차익, 채권은 이자와 시세 차익으로 구분해요."},{"title":"해당하는 자산만 더해 비율을 구해요","text":"시세 차익을 기대할 수 있는 주식 2,500달러와 채권 1,500달러를 더해요.","formula":"(2,500 + 1,500) ÷ 5,000 × 100 = 80%"},{"title":"금리·물가·안전성을 구분해요","text":"금리 상승은 새 예금의 이자 매력을 높이는 방향이고, 내전은 B국 채권의 상환 위험을 높일 수 있어요. 물가 상승은 구매력을 떨어뜨릴 수 있어요. 이 문항의 상황을 실제 투자 결과 보장으로 해석하지 않아요."}],"reasons":["배당을 기대하는 주식 투자액은 2,500달러로 가장 많아요.","주식 2,500달러 + 채권 1,500달러 = 4,000달러, 총액의 80%예요.","물가 상승은 같은 돈으로 살 수 있는 양을 줄여 가계의 실질 구매력과 소비를 위축시킬 수 있어요.","시중 금리 상승은 새로 예금에 투자할 때 이자 수익의 매력을 높이는 요인이에요. 기존 약정 금리가 자동으로 바뀐다는 뜻은 아니에요.","내전이 장기화된 B국 채권은 정치적 불안정에 따른 상환 위험을 고려해야 하므로 안전성만 보고 비중을 늘린다고 할 수 없어요."],"linked":false},{"id":"2025-1-10-19","year":2025,"grade":1,"month":10,"number":19,"modules":["cost","ripple"],"image":"assets/exams/2025-1-10-19.jpg","pdfPage":5,"topic":"기회비용·부정적 외부 효과","level":3,"points":2.5,"prompt":"다음 자료에 대한 분석 및 추론으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑은 편익과 비용만을 고려하여 A상품 구입 여부를 결정한다. A상품을 구입하기 위해 대중교통을 이용하며, 구매에 소요되는 시간에는 아르바이트를 할 수 없어 임금을 받지 못한다. 표는 구입에 영향을 미치는 모든 요인을 금액으로 나타낸 것이다.</p><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">요인</th><th scope=\"col\">금액</th></tr></thead><tbody><tr><th scope=\"row\">A상품 구입에 따른 편익</th><td>(가)</td></tr><tr><th scope=\"row\">A상품 가격</th><td>3만 원</td></tr><tr><th scope=\"row\">대중교통 이용료</th><td>1만 원</td></tr><tr><th scope=\"row\">지급받지 못하는 임금</th><td>2만 원</td></tr></tbody></table></div><p>A상품은 소비할 때마다 다른 사람에게 일정액의 피해를 발생시킨다. 그런데 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">해당 피해액</u>은 소비자들의 A상품 구입에 따른 편익과 비용에 영향을 미치지 않는다. 이로 인해 <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">A상품은 사회적으로 적정한 수준보다 과다 거래된다</u>.</p></div>","options":["갑의 A상품 구입에 따른 명시적 비용과 암묵적 비용은 같다.","(가)가 5만 원이면, 갑은 A상품을 구입한다.","갑이 A상품을 구입할 때 ㉠은 매몰 비용이다.","㉡은 개별 소비자들의 A상품에 대한 윤리적 소비로 인해 발생한 현상이다.","㉡을 해결하기 위한 정부의 대책으로 A상품 소비자에 대한 세금 부과를 들 수 있다."],"correct":4,"summary":"다른 사람이 입는 피해를 소비자가 부담하지 않아 과다 거래되는 부정적 외부 효과예요. 세금은 그 비용을 소비자의 선택에 반영하도록 하는 수단이에요.","steps":[{"title":"실제 지출과 포기한 기회를 나눠요","text":"상품 가격과 교통비는 실제 지출, 받지 못한 임금은 포기한 기회의 가치예요.","formula":"명시적 비용 = 3만 + 1만 = 4만 원\n암묵적 비용 = 2만 원\n기회비용 = 4만 + 2만 = 6만 원"},{"title":"편익이 주어지면 전체 비용과 비교해요","text":"(가)가 5만 원이라면 기회비용 6만 원보다 작아요. 이 조건에서는 사지 않는 것이 합리적이에요.","formula":"순편익 = 편익 − 기회비용 = 5만 − 6만 = −1만 원"},{"title":"제3자의 피해를 확인해요","text":"소비자의 계산에서 빠진 피해가 다른 사람에게 생겨요. 사회적으로는 너무 많이 소비될 수 있으므로 정부는 세금을 부과해 소비를 줄이도록 유도할 수 있어요."}],"reasons":["명시적 비용은 가격과 교통비를 합한 4만 원, 암묵적 비용은 포기한 임금 2만 원으로 서로 달라요.","편익 5만 원에서 기회비용 6만 원을 빼면 −1만 원이에요. 구입하지 않는 쪽이 합리적이에요.","㉠은 제3자에게 발생하지만 소비자의 계산에 반영되지 않은 피해예요. 이미 지출해 회수할 수 없는 매몰 비용과 구분해요.","타인의 피해가 소비자의 선택에 반영되지 않는 부정적 외부 효과 때문이에요. 윤리적 소비가 원인은 아니에요.","소비자에게 세금을 부과하면 그 상품의 소비 비용이 커져 과다 소비를 줄이는 방향으로 작용해요."],"linked":true},{"id":"2025-1-10-21","year":2025,"grade":1,"month":10,"number":21,"modules":["trade"],"image":"assets/exams/2025-1-10-21.jpg","pdfPage":5,"topic":"글로벌 생산 네트워크","level":2,"points":1.5,"prompt":"다음 자료에 대한 옳은 설명만을 보기에서 있는 대로 고른 것은?","body":"<div class=\"ep-passage\"><p><span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">세계화</u>로 공간적 분업이 활발해지며 다국적 기업들이 성장하고 있다. 다국적 기업은 본사, <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">연구소,</u> <span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">생산 공장</u> 등을 세계 각지에 두고 운영한다. 개발 도상국에 공장이 들어서면 <strong>(가)</strong> 같은 긍정적 영향이 있지만, 경쟁력이 부족한 현지 기업의 생산 활동이 위축될 우려도 있다.</p><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"network\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2025-1-10-21-network\" data-src=\"assets/exams/materials/2025-1-10-21-network.png\" data-title=\"다국적 기업의 공간적 분업\" data-alt=\"미국 본사의 제품 기획, 스위스 연구소의 기술 개발, 베트남 생산 공장의 제품 조립을 보여 주는 원문 세 장면.\" aria-label=\"다국적 기업의 공간적 분업 크게 보기\"><img src=\"assets/exams/materials/2025-1-10-21-network.png\" width=\"1217\" height=\"603\" alt=\"미국 본사의 제품 기획, 스위스 연구소의 기술 개발, 베트남 생산 공장의 제품 조립을 보여 주는 원문 세 장면.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 다국적 기업의 공간적 분업</figcaption></figure><details class=\"ep-material-transcript\"><summary>자료 글로 읽기</summary><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">기능의 예</th><th scope=\"col\">활동</th></tr></thead><tbody><tr><th scope=\"row\">미국 본사</th><td>제품 기획</td></tr><tr><th scope=\"row\">스위스 연구소</th><td>기술 개발</td></tr><tr><th scope=\"row\">베트남 생산 공장</th><td>제품 조립</td></tr></tbody></table></div></details></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. (가)에는 일자리 증가가 들어갈 수 있다.</p><p>ㄴ. ㉠이 진행될수록 국제 교류의 시·공간적 제약이 커진다.</p><p>ㄷ. ㉡은 ㉢보다 생산비 절감이 유리한 곳에 주로 입지한다.</p></fieldset>","options":["ㄱ","ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"correct":0,"summary":"공장이 들어서면 일자리가 늘 수 있어 ㄱ이 옳아요. 세계화는 교류의 제약을 줄이며, 생산비 절감을 중시하는 기능은 연구소보다 생산 공장이에요.","steps":[{"title":"기능마다 필요한 조건이 달라요","text":"본사는 경영·기획, 연구소는 기술·전문 인력, 생산 공장은 생산비 등의 조건을 중요하게 보며 여러 지역에 나뉠 수 있어요."},{"title":"받아들이는 지역의 영향을 살펴요","text":"현지 공장은 고용을 늘릴 수 있지만, 현지 기업과의 경쟁 등 부정적 영향도 함께 고려해야 해요."},{"title":"보기의 방향을 확인해요","text":"국제 교류의 제약은 줄어드는 방향이에요. 생산비 절감이 유리한 입지를 특히 중시하는 것은 연구소보다 생산 공장이에요."}],"reasons":["공장 설립으로 해당 지역의 고용이 늘 수 있으므로 ㄱ만 옳아요.","세계화가 진행되면 국제 교류의 시·공간적 제약은 작아져요.","ㄱ은 맞지만 ㄷ은 연구소와 생산 공장의 입지 조건을 바꿔 설명했어요.","ㄴ과 ㄷ 모두 방향이 잘못되었어요.","ㄱ만 옳고 ㄴ·ㄷ은 틀려요."],"linked":true},{"id":"2025-1-10-23","year":2025,"grade":1,"month":10,"number":23,"modules":["trade"],"image":"assets/exams/2025-1-10-23.jpg","pdfPage":6,"topic":"절대우위·비교우위와 특화","level":2,"points":2,"prompt":"다음 무역 원리에 관한 갑과 을의 입장에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><div class=\"ep-material\"><strong>갑</strong><p>A국은 같은 양의 면화를 B국보다 적은 노동력으로, B국은 같은 양의 설탕을 A국보다 적은 노동력으로 생산할 수 있다. 각국이 더 적은 노동력으로 생산하는 상품에 집중하고 다른 상품을 무역으로 얻으면 양국 모두 이익을 얻을 수 있다.</p></div><div class=\"ep-material\"><strong>을</strong><p>한 국가가 모든 상품을 더 적은 노동력으로 생산해도 무역할 수 있다. 생산을 위해 포기하는 다른 상품의 양을 비교해야 한다. 아래의 C국이 <strong>(가)</strong>, D국이 <strong>(나)</strong>를 특화하여 무역하면 양국 모두 이익을 얻을 수 있다.</p></div><div class=\"ep-table-scroll\"><table><caption>각 상품 생산에 필요한 노동력</caption><thead><tr><th scope=\"col\">국가</th><th scope=\"col\">포도주 1단위</th><th scope=\"col\">면화 1단위</th></tr></thead><tbody><tr><th scope=\"row\">C국</th><td>80명</td><td>90명</td></tr><tr><th scope=\"row\">D국</th><td>120명</td><td>100명</td></tr></tbody></table></div></div>","options":["갑은 비교 우위에 기반하여 무역의 필요성을 주장한다.","갑, 을은 모두 특화를 통한 국제 분업의 필요성을 주장한다.","A국과 B국이 설탕 생산에 동일한 노동력을 투입하면 A국의 생산량이 더 많다.","C국과 D국 중 D국은 포도주·면화 생산에 모두 절대 우위가 있다.","(가)에는 면화, (나)에는 포도주가 들어간다."],"correct":1,"summary":"갑은 절대우위, 을은 비교우위를 기준으로 설명하지만, 둘 다 각국이 특정 상품을 특화하는 국제 분업의 필요성을 인정해요.","steps":[{"title":"비교 기준을 구분해요","text":"더 적은 노동력이라는 생산비 비교는 절대우위, 포기하는 다른 상품의 양은 기회비용에 따른 비교우위예요."},{"title":"C·D의 기회비용을 구해요","text":"노동 투입량 자료에서는 한 상품에 필요한 노동력을 다른 상품의 노동력으로 나눠요.","formula":"포도주 1단위의 기회비용: C국 면화 80/90 = 8/9, D국 면화 120/100 = 6/5\n면화 1단위의 기회비용: C국 포도주 9/8, D국 포도주 5/6"},{"title":"각자의 공통 주장과 특화를 확인해요","text":"C국은 포도주, D국은 면화의 기회비용이 더 낮아요. 기준은 달라도 두 입장 모두 특화와 국제 분업을 설명해요."}],"reasons":["갑은 더 적은 노동력으로 생산하는 절대우위에 기반해 설명해요.","갑과 을 모두 각국이 특정 상품 생산을 특화하고 교환해야 한다고 설명해요.","설탕 생산에 더 적은 노동력이 필요한 B국이 동일 노동력으로 더 많이 생산해요.","C국이 포도주 80<120, 면화 90<100으로 둘 다 절대우위예요.","C국은 포도주, D국은 면화에 비교우위가 있으므로 반대로 고쳐야 해요."],"linked":false},{"id":"2026-1-03-21","year":2026,"grade":1,"month":3,"number":21,"modules":["capitalism"],"image":"assets/exams/2026-1-03-21.jpg","pdfPage":5,"topic":"시장 경제·계획 경제","level":2,"points":2,"prompt":"다음 자료에 대한 옳은 설명만을 보기에서 고른 것은?","body":"<div class=\"ep-passage\"><p>교사는 나무 조각 ㉠~㉣을 이용하여 구조물 (가), (나)를 완성하도록 했다. 완성된 구조물마다 3개 조각에 시장 경제 체제 또는 계획 경제 체제 중 하나에 대한 옳은 설명만 일관되게 적혀 있어야 한다.</p><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"blocks\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-1-03-21-blocks\" data-src=\"assets/exams/materials/2026-1-03-21-blocks.png\" data-title=\"나무 조각과 경제 체제 구조물\" data-alt=\"구조물 (가)의 기준 조각에는 자유로운 경쟁 보장, (나)에는 정부 계획·명령 중시가 적혀 있다. ㉠~㉣ 나무 조각을 사용해 빈 부분을 완성한다.\" aria-label=\"나무 조각과 경제 체제 구조물 크게 보기\"><img src=\"assets/exams/materials/2026-1-03-21-blocks.png\" width=\"1185\" height=\"631\" alt=\"구조물 (가)의 기준 조각에는 자유로운 경쟁 보장, (나)에는 정부 계획·명령 중시가 적혀 있다. ㉠~㉣ 나무 조각을 사용해 빈 부분을 완성한다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 나무 조각과 경제 체제 구조물</figcaption></figure><details class=\"ep-material-transcript\"><summary>자료 글로 읽기</summary><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">구조물</th><th scope=\"col\">기준 조각에 적힌 내용</th></tr></thead><tbody><tr><th scope=\"row\">(가)</th><td>자유로운 경쟁 보장</td></tr><tr><th scope=\"row\">(나)</th><td>정부의 계획·명령 중시</td></tr></tbody></table></div></details></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. ㉠에 생산 수단의 국유화가 적혀 있다면 (가)를 완성하는 데 사용할 수 없다.</p><p>ㄴ. ㉡에 사적 이윤 추구 활동 보장이 적혀 있다면 (가)를 완성하는 데 사용할 수 있다.</p><p>ㄷ. ㉢에 민간 경제 주체의 자율성 강조가 적혀 있다면 (나)를 완성하는 데 사용할 수 있다.</p><p>ㄹ. ㉣에 시장 가격 기구에 의한 자원 배분 중시가 적혀 있다면 (나)를 완성하는 데 사용할 수 있다.</p></fieldset>","options":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"correct":0,"summary":"(가)는 자유 경쟁을 보장하는 시장 경제, (나)는 정부의 계획을 중시하는 계획 경제예요. ㄱ과 ㄴ이 옳아요.","steps":[{"title":"기준 조각으로 두 체제를 정해요","text":"자유로운 경쟁은 시장 경제, 정부의 계획·명령은 계획 경제의 특징이에요."},{"title":"생산 수단의 소유와 결정 방식을 비교해요","text":"국유화는 국가가 생산 수단을 소유하는 방향으로 계획 경제와 연결돼요. 사적 이윤 추구와 민간의 자율성은 시장 경제와 연결돼요."},{"title":"네 진술을 각각 분류해요","text":"ㄱ의 국유화는 (가)에 맞지 않으므로 사용할 수 없다는 말이 맞아요. ㄴ은 맞고, ㄷ·ㄹ은 (나)가 아니라 (가)의 특징이에요."}],"reasons":["ㄱ·ㄴ 모두 맞아요. 국유화는 (가)에 맞지 않고 사적 이윤 추구는 (가)에 맞아요.","ㄱ은 맞지만 ㄷ의 민간 자율성은 시장 경제의 특징이에요.","ㄴ은 맞지만 ㄷ은 계획 경제인 (나)에 넣을 수 없어요.","ㄴ은 맞지만 ㄹ의 시장 가격 기구는 (나)의 정부 계획·명령과 다르게 작동해요.","ㄷ과 ㄹ은 모두 시장 경제인 (가)에 해당하는 특징이에요."],"linked":false},{"id":"2026-1-03-25","year":2026,"grade":1,"month":3,"number":25,"modules":["finance"],"image":"assets/exams/2026-1-03-25.jpg","pdfPage":6,"topic":"예금·채권·주식의 특징","level":2,"points":2.5,"prompt":"다음 자료에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑은 현금 5,000만 원을 금융 상품 A~C에 투자하려 한다. AI는 갑의 투자 성향을 반영해 다음 포트폴리오를 제안했다. A~C는 각각 예금·주식·채권 중 하나이며, 아래 상품 소개는 모두 옳다.</p><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">상품</th><th scope=\"col\">비율</th><th scope=\"col\">상품 소개</th></tr></thead><tbody><tr><th scope=\"row\">A</th><td>70%</td><td>금융 기관에 일정 금액을 맡기고 이자를 받음</td></tr><tr><th scope=\"row\">B</th><td>20%</td><td>기업이나 정부에 돈을 빌려주고 일정한 이익을 얻음</td></tr><tr><th scope=\"row\">C</th><td>10%</td><td>(가)</td></tr></tbody></table></div></div>","options":["A는 예금, B는 주식, C는 채권이다.","A는 C에 비해 일반적으로 안전성은 높고 수익성은 낮다.","C는 B와 달리 다른 사람에게 팔아 이익을 얻을 수 있다.","(가)에는 만기일이 되면 배당금을 받음이 들어갈 수 있다.","투자 비율이 10%인 금융 상품은 원금 손실의 가능성이 없다."],"correct":1,"summary":"돈을 맡기는 A는 예금, 빌려주는 B는 채권, 남은 C는 주식이에요. 일반적으로 예금은 주식보다 안전성이 높고 수익성은 낮아요.","steps":[{"title":"돈을 맡기는지, 빌려주는지 구분해요","text":"예금은 금융 기관에 돈을 맡기고, 채권은 기업·정부 등에 돈을 빌려준 관계를 나타내요. 따라서 A는 예금, B는 채권, C는 주식이에요."},{"title":"안전성과 수익성을 함께 읽어요","text":"일반적인 상품 특징을 비교하는 문제예요. 예금과 주식은 기대 수익뿐 아니라 원금 손실 위험도 다르게 살펴야 해요."},{"title":"주식과 채권의 공통점을 확인해요","text":"둘 다 팔 때 가격이 올라 시세 차익을 얻을 수 있어요. 주식에는 정해진 만기가 없고, 배당이 항상 보장되는 것도 아니에요."}],"reasons":["B는 기업·정부에 돈을 빌려주는 채권이고 C가 주식이에요.","A 예금은 C 주식보다 일반적으로 안전성이 높고 수익성은 낮아요.","주식뿐 아니라 채권도 시장에서 거래해 시세 차익을 얻을 수 있어요.","주식은 정해진 만기가 없고 배당이 확정되어 지급되는 상품도 아니에요.","주식은 원금 손실 가능성이 있어요. AI가 추천했다는 사실이 손실 위험을 없애지는 않아요."],"linked":false},{"id":"2026-1-06-07","year":2026,"grade":1,"month":6,"number":7,"modules":["ripple"],"image":"assets/exams/2026-1-06-07.jpg","pdfPage":2,"topic":"정부·기업·시민사회의 역할","level":2,"points":2,"prompt":"A~C에 대한 옳은 설명만을 보기에서 고른 것은?","body":"<p>A~C는 각각 정부·시민사회·기업 중 하나이다.</p><div class=\"ep-passage\"><div class=\"ep-material\"><strong>행위 주체들의 노력</strong><p><strong>A:</strong> 탄소 중립을 국가 전략으로 수립하고 환경 오염 물질 배출 규제 등 제도를 마련해 시행한다.<br><strong>B:</strong> 친환경·사회적 책임·투명한 지배 구조로 지속가능발전을 추구하는 경영 방식을 채택한다.<br><strong>C:</strong> WWF·그린피스 같은 국제적인 민간 환경 단체를 통해 환경 문제에 대응한다.</p></div></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. A는 다양한 국제 협약의 주체로서 국제 사회와 협력할 수 있다.</p><p>ㄴ. B는 환경 관련 법을 제정하며 법적 제재를 가할 수 있다.</p><p>ㄷ. C는 A의 활동이 환경에 부정적인 영향을 미치지 않도록 감시할 수 있다.</p><p>ㄹ. B와 달리 C는 친환경 제품을 개발·생산하여 탄소 배출을 줄이려 노력한다.</p></fieldset>","options":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"correct":1,"summary":"A는 정부, ESG 경영을 하는 B는 기업, 민간 환경 단체로 활동하는 C는 시민사회예요. 정부의 국제 협력과 시민사회의 감시 역할을 설명한 ㄱ·ㄷ이 옳아요.","steps":[{"title":"기업의 ESG 경영을 알아봐요","text":"친환경(E)·사회적 책임(S)·지배 구조(G)는 기업의 ESG 경영과 연결돼요. 따라서 B는 기업이에요."},{"title":"제도를 시행하는 정부와 감시하는 시민사회를 나눠요","text":"배출 규제 등 국가 제도를 마련하는 A는 정부예요. 시민들이 자발적으로 참여하는 민간 환경 단체 C는 정부의 정책과 활동을 감시할 수 있어요."},{"title":"각 보기의 주어를 확인해요","text":"ㄴ의 법적 제재는 정부, ㄹ의 친환경 제품 개발·생산은 기업의 역할이에요. 주체가 바뀐 보기라 틀려요."}],"reasons":["ㄱ은 맞지만 ㄴ의 법적 제재 주체는 기업 B가 아니라 정부예요.","정부의 국제 협력과 시민사회의 감시 활동을 설명한 ㄱ·ㄷ이 모두 맞아요.","ㄷ은 맞지만 ㄴ의 주체가 기업으로 잘못 연결되었어요.","ㄴ과 ㄹ 모두 주체가 바뀌었어요. 법적 제재는 정부, 친환경 제품 생산은 기업이에요.","ㄷ은 맞지만 ㄹ은 친환경 제품을 개발·생산하는 기업 B의 역할로 고쳐야 해요."],"linked":true},{"id":"2026-1-09-20","year":2026,"grade":1,"month":9,"number":20,"modules":["ripple"],"image":"assets/exams/2026-1-09-20.jpg","pdfPage":5,"topic":"외부 효과 개선·주체별 역할","level":2,"points":2,"prompt":"다음 기후 위기 대응 보고서에 대한 설명으로 옳은 것은?","body":"<p>A·B는 각각 기업·시민 단체 중 하나이다. 다음은 갑국의 보고서 일부이다.</p><div class=\"ep-passage\"><div class=\"ep-visual-pair\"><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"carbon\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-1-09-20-carbon\" data-src=\"assets/exams/materials/2026-1-09-20-carbon.png\" data-title=\"연간 이산화 탄소 배출 추이\" data-alt=\"1960~2025년 화석 에너지 사용에 따른 연간 이산화 탄소 배출 추이. 세로축 단위는 억 톤이다. 석탄은 실선, 석유는 파선, 천연가스는 점선이며 세 선 모두 증가 추세이다.\" aria-label=\"연간 이산화 탄소 배출 추이 크게 보기\"><img src=\"assets/exams/materials/2026-1-09-20-carbon.png\" width=\"599\" height=\"700\" alt=\"1960~2025년 화석 에너지 사용에 따른 연간 이산화 탄소 배출 추이. 세로축 단위는 억 톤이다. 석탄은 실선, 석유는 파선, 천연가스는 점선이며 세 선 모두 증가 추세이다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 연간 이산화 탄소 배출 추이</figcaption></figure><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">행위 주체</th><th scope=\"col\">대응 노력</th></tr></thead><tbody><tr><th scope=\"row\">A</th><td>공장 전력 100%를 재생 에너지로 공급하기 위한 경영 계획 수립·운영</td></tr><tr><th scope=\"row\">정부</th><td>(가)</td></tr><tr><th scope=\"row\">B</th><td>(나)</td></tr></tbody></table></div></div></div>","options":["A는 환경 관련 법률을 제정하는 주체이다.","B는 재화와 서비스를 생산하는 주체이다.","B와 달리 A는 정부를 감시하며 시민 운동을 전개한다.","(가)에는 온실가스를 배출하는 화석 에너지 사용량에 따른 조세 부과가 들어갈 수 있다.","(나)에는 온실가스 불법 배출 사업장에 대한 행정 제재가 들어갈 수 있다."],"correct":3,"summary":"공장 전력의 조달 방식을 바꾸는 A는 기업이고 B는 시민 단체예요. 정부는 오염 유발 활동에 조세를 부과해 줄이도록 유도할 수 있어요.","steps":[{"title":"A의 활동을 단서로 주체를 찾아요","text":"공장의 경영 계획을 세우고 생산 방식을 바꾸는 활동은 기업의 역할이에요. A가 기업이므로 B는 시민 단체예요."},{"title":"세금·행정 제재와 시민 운동을 구별해요","text":"정부는 세금 부과·행정 제재 같은 제도적 수단을 사용할 수 있어요. 시민 단체는 감시·비판·시민 운동으로 참여해요."},{"title":"배출에 대한 조세의 방향을 이해해요","text":"화석 에너지 사용에 비용을 부과하면 오염을 일으키는 활동을 줄이도록 유도할 수 있어 정부의 역할에 들어맞아요."}],"reasons":["A는 기업이에요. 환경 관련 법률 제정과 같은 국가의 역할과 구분해요.","재화와 서비스 생산은 기업 A의 역할이며 B는 시민 단체예요.","정부 감시와 시민 운동은 B 시민 단체의 역할이에요.","오염을 유발하는 화석 에너지 사용량에 조세를 부과하는 것은 정부가 사용할 수 있는 수단이에요.","행정 제재는 정부가 할 수 있는 조치이며 시민 단체 B의 권한이 아니에요."],"linked":true},{"id":"2026-1-10-15","year":2026,"grade":1,"month":10,"number":15,"modules":["trade"],"image":"assets/exams/2026-1-10-15.jpg","pdfPage":4,"topic":"절대우위와 비교우위 구분","level":2,"points":2,"prompt":"다음 통합사회 수업에서 교사의 질문에 대한 답변으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑국·을국은 노동만을 생산 요소로 사용해 X재와 Y재만 생산한다. 각 재화의 1단위 추가 생산에 따른 기회비용은 일정하다.</p><div class=\"ep-table-scroll\"><table><caption>생산에 필요한 노동자 수</caption><thead><tr><th scope=\"col\">국가</th><th scope=\"col\">X재 1단위</th><th scope=\"col\">Y재 1단위</th></tr></thead><tbody><tr><th scope=\"row\">갑국</th><td>8명</td><td>4명</td></tr><tr><th scope=\"row\">을국</th><td>6명</td><td>2명</td></tr></tbody></table></div></div>","options":["갑국은 X재와 Y재 생산에 모두 절대 우위를 가집니다.","을국의 Y재 1단위 생산의 기회비용은 X재 3단위입니다.","X재 1단위 생산의 기회비용은 갑국이 을국보다 큽니다.","갑국은 X재 생산에, 을국은 Y재 생산에 비교 우위를 가집니다.","양국 간 무역이 발생한다면 Y재를 수출하는 국가는 갑국입니다."],"correct":3,"summary":"을국은 두 상품 모두 더 적은 노동이 필요하지만, X재의 기회비용은 갑국이 더 낮아요. 갑국 X재·을국 Y재에 비교우위가 있어요.","steps":[{"title":"절대우위는 필요한 노동의 크기로 비교해요","text":"X재는 6<8, Y재는 2<4이므로 을국이 두 재화 모두 절대우위예요."},{"title":"기회비용은 같은 나라 안에서 나눠요","text":"X재를 만드는 노동으로 Y재를 몇 개 만들 수 있는지 구해요. Y재는 반대로 나눠요.","formula":"갑국: X재 기회비용 Y재 8/4=2, Y재 기회비용 X재 4/8=1/2\n을국: X재 기회비용 Y재 6/2=3, Y재 기회비용 X재 2/6=1/3"},{"title":"각 재화에서 더 낮은 쪽을 찾아요","text":"X재는 2<3으로 갑국, Y재는 1/3<1/2로 을국이 비교우위예요."}],"reasons":["필요 노동이 더 적은 을국이 두 재화 모두 절대우위예요.","을국 Y재의 기회비용은 X재 2/6=1/3단위예요.","X재의 기회비용은 갑국 2, 을국 3으로 갑국이 작아요.","각 재화의 기회비용이 낮은 갑국 X재, 을국 Y재로 올바르게 연결했어요.","Y재에 비교우위가 있는 을국이 Y재를 수출해요."],"linked":false},{"id":"2026-1-10-17","year":2026,"grade":1,"month":10,"number":17,"modules":["capitalism"],"image":"assets/exams/2026-1-10-17.jpg","pdfPage":5,"topic":"신자유주의의 정책","level":1,"points":1.5,"prompt":"밑줄 친 정책의 내용으로 가장 적절한 것은?","body":"<div class=\"ep-passage\"><div class=\"ep-material\"><strong>마거릿 대처의 연설 일부</strong><p>경기 침체기에 많은 사람들이 자신의 잘못이 아닌 이유로 생계를 잃을 수 있습니다. …(중략)… 정부의 역할은 사람들이 자유롭고 두려움 없이 일상생활을 할 수 있도록 보장하고 약자와 도움이 필요한 사람들을 보호하는 것이어야 합니다. 그러나 영국, 미국 모두에서 정부의 영향력은 이러한 제한적인 수준을 훨씬 넘어섰습니다. 저는 과거에 영국에서 시도했으나 실패했다고 생각하는 정부의 개입 방안들에 대해 논의하고 싶습니다.</p></div><p>1970년대 두 차례의 석유 파동 이후 경기 침체와 물가 상승이 동반되는 스태그플레이션이 나타났다. 정부의 적극적인 개입이 문제를 해결하지 못하자, 대처는 신자유주의에 기반해 정부 역할을 축소시키는 <span class=\"ep-reference\"></span><u class=\"ep-underlined\" data-ref=\"policy\">정책</u>을 추진했다.</p></div>","options":["노동 시장의 유연화","사회 보장 제도의 확대","기업에 대한 규제 강화","생산 수단의 사회적 소유","실업 문제 해결을 위한 대규모 공공사업 시행"],"correct":0,"summary":"정부 개입을 줄이고 시장의 자율성을 강조하는 신자유주의 정책을 고르면 돼요. 노동 시장의 유연화가 이에 해당해요.","steps":[{"title":"자료가 이미 알려 준 입장을 읽어요","text":"핵심은 정부 역할 축소와 신자유주의예요. 어려운 연설 전체를 암기할 필요 없이 이 방향을 기준으로 판단해요."},{"title":"유연화의 의미를 풀어 봐요","text":"노동 시장의 유연화는 고용·임금 등에 관한 조정이 더 유연하게 이루어지도록 하는 방향으로, 신자유주의 정책과 연결돼요."},{"title":"정부 역할을 늘리는 정책을 구별해요","text":"사회 보장 확대·규제 강화·대규모 공공사업은 정부의 적극적 역할에 가까워요."}],"reasons":["시장 자율성을 강조하는 신자유주의와 연결되는 정책이에요.","사회 보장 제도의 확대는 정부 역할을 늘리는 방향이에요.","기업 규제 강화는 자료가 강조하는 규제 완화와 반대 방향이에요.","생산 수단의 사회적 소유는 사회주의와 연결돼요. 자본주의의 사유 재산 원리와 구별해요.","정부의 대규모 공공사업은 뉴딜 정책 등 수정 자본주의와 연결돼요."],"linked":false},{"id":"2026-1-10-18","year":2026,"grade":1,"month":10,"number":18,"modules":["finance"],"image":"assets/exams/2026-1-10-18.jpg","pdfPage":5,"topic":"투자 비중·수익의 종류","level":2,"points":2,"prompt":"다음 금융 상품 상담 내용에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><div class=\"ep-material\"><strong>상담 질문</strong><p>갑은 총 1억 원 중 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">정기 예금</u> 7천만 원, <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">주식</u> 2천만 원, <span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">채권</u> 1천만 원에 투자하고 있다. 정기 예금의 비중이 높은데 은행이 파산하면 예금을 찾지 못하는지 물었다.</p></div><div class=\"ep-material\"><strong>출제 당시 상담 답변</strong><p>우리나라는 예금자 보호 제도를 운영한다. 금융 회사가 예금을 지급하지 못하면 예금보험공사가 보호 한도 안에서 보험금을 지급한다. 원문은 2025년 9월 1일부터 금융 회사별 1인당 보호 한도가 원금과 이자를 합해 1억 원으로 상향된 조건을 설명한다.</p></div></div>","options":["㉢은 이자 수익을 기대할 수 없다.","㉡에 비해 ㉠은 안전성이 낮다.","㉢과 달리 ㉡은 만기가 있다.","총투자액 중 배당 수익을 기대할 수 있는 금융 상품 투자액의 비율은 10%이다.","총투자액 중 시세 차익을 기대할 수 있는 금융 상품 투자액의 비율은 30%이다."],"correct":4,"summary":"시세 차익은 주식과 채권에서 기대할 수 있어요. 2천만 원과 1천만 원을 더한 3천만 원이 총 1억 원의 30%예요.","steps":[{"title":"상품별 금액을 정리해요","text":"정기 예금 70%, 주식 20%, 채권 10%예요. 금액 합계가 1억 원인지 먼저 확인해요."},{"title":"수익의 이름에 맞는 상품을 골라요","text":"배당은 주식만, 시세 차익은 주식·채권 모두에서 기대할 수 있어요.","formula":"배당 가능 상품 비중 = 2천만 ÷ 1억 × 100 = 20%\n시세 차익 가능 상품 비중 = (2천만 + 1천만) ÷ 1억 × 100 = 30%"},{"title":"만기와 안전성도 구별해요","text":"정기 예금·채권은 만기가 있고, 주식은 정해진 만기가 없어요. 일반적으로 정기 예금은 주식보다 안전성이 높아요."}],"reasons":["채권은 이자 수익을 기대할 수 있어요.","정기 예금은 주식보다 일반적으로 안전성이 높아요.","채권에는 만기가 있고 주식에는 정해진 만기가 없어요.","배당은 주식에 해당하므로 20%예요.","주식 20%와 채권 10%를 합한 30%가 맞아요."],"linked":false},{"id":"2026-2-03-10","year":2026,"grade":2,"month":3,"number":10,"modules":["cost"],"image":"assets/exams/2026-2-03-10.jpg","pdfPage":3,"topic":"암묵적 비용·순편익","level":3,"points":2.5,"prompt":"다음 자료에 대한 옳은 설명만을 보기에서 고른 것은?","body":"<div class=\"ep-passage\"><p>카페에 간 갑은 커피 1잔 또는 주스 1잔 중 하나를 편익과 기회비용만 고려해 합리적으로 선택하려 한다. 커피 선택의 기회비용은 8,500원이다. 순편익은 편익에서 기회비용을 뺀 값이며, 다른 조건은 고려하지 않는다.</p><div class=\"ep-table-scroll\"><table><caption>단위: 원</caption><thead><tr><th scope=\"col\">구분</th><th scope=\"col\">커피</th><th scope=\"col\">주스</th></tr></thead><tbody><tr><th scope=\"row\">가격</th><td>6,000</td><td>5,000</td></tr><tr><th scope=\"row\">편익</th><td>9,000</td><td>㉠</td></tr></tbody></table></div></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. ㉠은 7,500이다.</p><p>ㄴ. 주스 선택의 기회비용은 7,000원이다.</p><p>ㄷ. 커피 선택의 순편익은 500원, 주스 선택의 순편익은 −500원이다.</p><p>ㄹ. 주스 선택의 명시적 비용은 암묵적 비용보다 1,000원 많다.</p></fieldset>","options":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"correct":1,"summary":"커피의 기회비용에서 가격을 빼면 포기한 주스의 이익이 나와요. 주스의 편익은 7,500원이며 두 순편익은 500원과 −500원이에요. ㄱ·ㄷ이 옳아요.","steps":[{"title":"알고 있는 기회비용에서 거꾸로 구해요","text":"커피 가격은 명시적 비용이에요. 남는 2,500원이 포기한 주스의 이익이므로 주스 가격을 더하면 주스의 편익이 돼요.","formula":"커피의 암묵적 비용 = 8,500 − 6,000 = 2,500원\n주스 편익 = 2,500 + 5,000 = 7,500원"},{"title":"선택을 바꾸어 주스의 비용을 구해요","text":"주스를 선택하면 커피의 편익에서 가격을 뺀 이익을 포기해요.","formula":"주스의 암묵적 비용 = 9,000 − 6,000 = 3,000원\n주스의 기회비용 = 5,000 + 3,000 = 8,000원"},{"title":"순편익과 보기의 차액을 확인해요","text":"편익에서 기회비용을 빼요. 주스의 명시적·암묵적 비용 차이는 1,000원이 아닌 2,000원이에요.","formula":"커피: 9,000 − 8,500 = 500원\n주스: 7,500 − 8,000 = −500원\n5,000 − 3,000 = 2,000원"}],"reasons":["ㄱ은 맞지만 ㄴ은 틀려요. 주스의 기회비용은 5,000 + 3,000 = 8,000원이에요.","ㄱ의 7,500원과 ㄷ의 두 순편익 500원·−500원이 모두 맞아요.","ㄷ은 맞지만 ㄴ의 7,000원은 틀려요. 주스의 기회비용은 8,000원이에요.","ㄴ은 8,000원으로, ㄹ의 차이는 2,000원으로 고쳐야 해요.","ㄷ은 맞지만 ㄹ의 차이는 1,000원이 아닌 2,000원이에요."],"linked":false},{"id":"2026-2-03-21","year":2026,"grade":2,"month":3,"number":21,"modules":["finance"],"image":"assets/exams/2026-2-03-21.jpg","pdfPage":5,"topic":"주식·채권의 공통점과 차이","level":3,"points":2.5,"prompt":"다음 자료에 대한 옳은 설명만을 보기에서 있는 대로 고른 것은?","body":"<div class=\"ep-passage\"><p>갑·을·병은 카드 A~C를 한 세트씩 받았다.</p><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"cards\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-2-03-21-cards\" data-src=\"assets/exams/materials/2026-2-03-21-cards.png\" data-title=\"금융 상품 카드 A·B·C\" data-alt=\"카드 A: 시세 차익을 기대할 수 있음. 카드 B: 기업에 대한 지분을 나타내는 증서임. 카드 C: 이자 수익을 기대할 수 있음.\" aria-label=\"금융 상품 카드 A·B·C 크게 보기\"><img src=\"assets/exams/materials/2026-2-03-21-cards.png\" width=\"933\" height=\"283\" alt=\"카드 A: 시세 차익을 기대할 수 있음. 카드 B: 기업에 대한 지분을 나타내는 증서임. 카드 C: 이자 수익을 기대할 수 있음.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 금융 상품 카드 A·B·C</figcaption></figure><details class=\"ep-material-transcript\"><summary>자료 글로 읽기</summary><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">카드</th><th scope=\"col\">적힌 내용</th></tr></thead><tbody><tr><th scope=\"row\">A</th><td>시세 차익을 기대할 수 있음</td></tr><tr><th scope=\"row\">B</th><td>기업에 대한 지분을 나타내는 증서임</td></tr><tr><th scope=\"row\">C</th><td>이자 수익을 기대할 수 있음</td></tr></tbody></table></div></details><div class=\"ep-material\"><strong>가위바위보 규칙</strong><p>주식만의 특징 카드 → 가위<br>채권만의 특징 카드 → 바위<br>주식·채권 공통 특징 카드 → 보</p></div><p>한 번 사용한 카드는 다시 사용할 수 없다. 이기면 2점, 비기면 1점, 지면 0점을 얻는다. 갑의 총점은 4점, 을·병의 총점은 각각 1점이다.</p><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"hands\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-2-03-21-hands\" data-src=\"assets/exams/materials/2026-2-03-21-hands.png\" data-title=\"갑·을·병의 가위바위보 결과표\" data-alt=\"첫 대결은 갑의 표시되지 않은 손과 을의 보, 둘째는 을의 바위와 병의 표시되지 않은 손, 셋째는 병의 가위와 갑의 표시되지 않은 손이다. 음영은 해당 내용을 표시하지 않은 것이다.\" aria-label=\"갑·을·병의 가위바위보 결과표 크게 보기\"><img src=\"assets/exams/materials/2026-2-03-21-hands.png\" width=\"1073\" height=\"528\" alt=\"첫 대결은 갑의 표시되지 않은 손과 을의 보, 둘째는 을의 바위와 병의 표시되지 않은 손, 셋째는 병의 가위와 갑의 표시되지 않은 손이다. 음영은 해당 내용을 표시하지 않은 것이다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 갑·을·병의 가위바위보 결과표</figcaption></figure><details class=\"ep-material-transcript\"><summary>자료 글로 읽기</summary><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">대결</th><th scope=\"col\">왼쪽 학생의 선택</th><th scope=\"col\">오른쪽 학생의 선택</th></tr></thead><tbody><tr><th scope=\"row\">갑 대 을</th><td>표시되지 않음</td><td>보</td></tr><tr><th scope=\"row\">을 대 병</th><td>바위</td><td>표시되지 않음</td></tr><tr><th scope=\"row\">병 대 갑</th><td>가위</td><td>표시되지 않음</td></tr></tbody></table></div></details></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. 갑은 을과의 가위바위보에서 카드 B를 선택하였다.</p><p>ㄴ. 갑은 병과의 가위바위보에서 카드 A를 선택하였다.</p><p>ㄷ. 병은 을과의 가위바위보에서 카드 C를 선택하였다.</p></fieldset>","options":["ㄱ","ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"correct":2,"summary":"A는 공통 특징인 보, B는 주식만의 특징인 가위, C는 채권만의 특징인 바위예요. 갑이 두 번 모두 이긴다는 조건을 적용하면 ㄱ·ㄷ이 옳아요.","steps":[{"title":"금융 특징을 손 모양으로 바꿔요","text":"주식·채권은 모두 시세 차익을 기대할 수 있어 A는 보예요. 기업 지분인 B는 주식이므로 가위, 이자가 있는 C는 채권이므로 바위예요.","formula":"A = 보 / B = 가위 / C = 바위"},{"title":"갑의 총점 4점을 먼저 사용해요","text":"갑은 두 번 모두 이겨야 4점이에요. 을의 보를 이기려면 가위 B, 병의 가위를 이기려면 바위 C를 내야 해요."},{"title":"나머지 점수로 확인해요","text":"을은 갑에게 져서 0점이므로 병과는 비겨 1점을 얻어요. 을의 바위와 비기려면 병도 바위 C를 내야 해요. ㄱ·ㄷ이 맞아요."}],"reasons":["ㄱ은 맞지만 ㄷ도 맞으므로 있는 대로 고른 답으로는 부족해요.","갑은 병의 가위를 이기기 위해 바위 C를 내요. A는 보이므로 ㄴ은 틀려요.","갑은 을의 보를 이기는 가위 B, 병은 을의 바위와 비기는 바위 C를 선택해요. ㄱ·ㄷ이 맞아요.","ㄷ은 맞지만 ㄴ은 틀려요. 갑이 병을 이기려면 카드 C가 필요해요.","ㄱ·ㄷ은 맞지만 ㄴ이 틀려요."],"linked":false},{"id":"2026-2-03-22","year":2026,"grade":2,"month":3,"number":22,"modules":["capitalism"],"image":"assets/exams/2026-2-03-22.jpg","pdfPage":6,"topic":"대공황·뉴딜 정책","level":2,"points":2.5,"prompt":"다음 그림이 그려질 당시에 있었던 사실로 옳은 것은?","body":"<div class=\"ep-passage\"><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"mural\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-2-03-22-mural\" data-src=\"assets/exams/materials/2026-2-03-22-mural.png\" data-title=\"미국 우체국 본부의 벽화\" data-alt=\"미국 우체국 본부에 그려진 벽화. 철도와 거리에서 사람들이 분주하게 일하는 모습이다.\" aria-label=\"미국 우체국 본부의 벽화 크게 보기\"><img src=\"assets/exams/materials/2026-2-03-22-mural.png\" width=\"922\" height=\"494\" alt=\"미국 우체국 본부에 그려진 벽화. 철도와 거리에서 사람들이 분주하게 일하는 모습이다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 미국 우체국 본부의 벽화</figcaption></figure><div class=\"ep-material\"><strong>미국 우체국 본부의 벽화</strong><p>사람들이 분주하게 일하는 거리를 표현했지만 당시 경제 상황은 좋지 않았다. 루스벨트 정부가 설립한 공공사업 진흥국[WPA]은 실업 위기에 처한 화가들을 위해 공공건물에 벽화를 그리는 사업을 진행하였고, 이 그림도 정부의 지원으로 제작되었다.</p></div></div>","options":["애덤 스미스가 국부론을 저술하였다.","석유 파동으로 스태그플레이션이 발생하였다.","중상주의 정책 아래 신항로 개척이 이루어졌다.","케인스의 이론에 입각한 경제 정책이 시행되었다.","신자유주의의 영향으로 많은 공기업이 민영화되었다."],"correct":3,"summary":"루스벨트 정부가 공공사업으로 일자리를 만든다는 단서가 중요해요. 대공황 이후 뉴딜 정책과 케인스의 정부 개입 논리에 연결돼요.","steps":[{"title":"인물과 정책의 단서를 찾아요","text":"루스벨트·공공사업·실업 해결은 1929년 대공황 이후의 뉴딜 정책을 가리켜요."},{"title":"정책의 작동 방향을 이해해요","text":"정부가 사업을 벌여 일자리를 만들고 소득·소비를 늘리려는 방향이에요. 시장에 대한 정부의 적극적 역할을 강조하는 수정 자본주의와 연결돼요."},{"title":"다른 시기의 사실을 제외해요","text":"중상주의·산업 혁명 시기와, 1970년대 석유 파동 이후의 신자유주의를 구별하면 ④가 남아요."}],"reasons":["국부론 출간은 1776년으로 대공황 이전이에요.","석유 파동으로 인한 스태그플레이션은 1970년대의 상황이에요.","신항로 개척과 중상주의는 더 이른 상업 자본주의 시기와 연결돼요.","케인스는 정부의 적극적 개입으로 불황을 해결해야 한다고 보았어요. 자료의 공공사업과 연결돼요.","공기업 민영화는 정부 역할 축소를 강조하는 신자유주의와 연결돼요."],"linked":false},{"id":"2026-2-03-25","year":2026,"grade":2,"month":3,"number":25,"modules":["trade"],"image":"assets/exams/2026-2-03-25.jpg","pdfPage":6,"topic":"노동 투입량·비교우위","level":3,"points":2.5,"prompt":"다음 자료에 대한 분석으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑국·을국은 X재와 Y재만 생산한다. 노동자 수는 각각 120명이고 모든 자원을 활용한다. 비교우위 재화만 생산해 양국 모두 이익을 얻는 비율로 양국 간에만 거래 비용 없이 교역한다. 각 재화의 기회비용은 일정하다.</p><div class=\"ep-table-scroll\"><table><caption>필요 노동자 수와 기회비용</caption><thead><tr><th scope=\"col\">국가</th><th scope=\"col\">X재 1개</th><th scope=\"col\">Y재 1개</th><th scope=\"col\">X재 1개의 기회비용</th></tr></thead><tbody><tr><th scope=\"row\">갑국</th><td>2명</td><td>4명</td><td>㉠</td></tr><tr><th scope=\"row\">을국</th><td>4명</td><td>㉡</td><td>Y재 2/3개</td></tr></tbody></table></div></div>","options":["㉠은 Y재 2개, ㉡은 6명이다.","Y재 최대 생산 가능량은 갑국이 을국보다 적다.","노동자 1명당 X재 생산량은 을국이 갑국보다 많다.","Y재 1개 생산의 기회비용은 갑국이 을국보다 작다.","갑국은 X재 생산에, 을국은 Y재 생산에 비교 우위를 가진다."],"correct":4,"summary":"생산에 필요한 노동자 수를 나누면 기회비용이 나와요. X재는 갑국의 1/2이 을국의 2/3보다 낮고, Y재는 을국의 3/2가 갑국의 2보다 낮아요.","steps":[{"title":"빈칸을 계산해요","text":"갑국 X재는 노동 2명분으로 Y재 1/2개를 만들 수 있는 기회를 포기해요. 을국의 X재 기회비용 2/3을 이용하면 Y재 노동자 수도 구할 수 있어요.","formula":"㉠ = 2 ÷ 4 = Y재 1/2개\n4 ÷ ㉡ = 2/3 → ㉡ = 6명"},{"title":"재화별로 더 적게 포기하는 나라를 찾아요","text":"X재 기회비용은 갑국 1/2, 을국 2/3이에요. Y재는 반대로 갑국 2, 을국 3/2예요. 따라서 갑국 X재, 을국 Y재에 비교우위가 있어요."},{"title":"최대 생산량과 노동 생산성을 확인해요","text":"120명을 한 재화에 모두 투입하는 경우와 노동자 1명 기준을 각각 계산해요.","formula":"Y재 최대: 갑국 120/4=30개, 을국 120/6=20개\n노동 1명당 X재: 갑국 1/2개, 을국 1/4개"}],"reasons":["㉡ 6명은 맞지만 ㉠은 Y재 2개가 아닌 1/2개예요.","Y재 최대 생산량은 갑국 30개, 을국 20개로 갑국이 많아요.","노동 1명당 X재는 갑국 1/2개, 을국 1/4개로 갑국이 많아요.","Y재 기회비용은 갑국 X재 2개, 을국 X재 3/2개로 을국이 작아요.","X재는 갑국, Y재는 을국이 더 낮은 기회비용으로 생산할 수 있어요."],"linked":false},{"id":"2026-2-06-13","year":2026,"grade":2,"month":6,"number":13,"modules":["finance"],"image":"assets/exams/2026-2-06-13.jpg","pdfPage":4,"topic":"포트폴리오·금리·구매력","level":3,"points":2.5,"prompt":"다음 자료에 대한 분석 및 추론으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>A~C는 정기 예금·주식·채권 중 하나이며 각 금융 상품의 일반적인 특징을 가진다. 갑은 t 시점의 원금과 수익금 전액을 t+1 시점에 재투자하면서 구성 비율을 조정하려 한다.</p><div class=\"ep-table-scroll\"><table><caption>표 1 · t 시점 포트폴리오</caption><thead><tr><th scope=\"col\">구분</th><th scope=\"col\">A</th><th scope=\"col\">B</th><th scope=\"col\">C</th></tr></thead><tbody><tr><th scope=\"row\">구성 비율</th><td>50%</td><td>30%</td><td>20%</td></tr><tr><th scope=\"row\">이자 수익</th><td>있음</td><td>없음</td><td>있음</td></tr><tr><th scope=\"row\">시세 차익</th><td>없음</td><td>있음</td><td>있음</td></tr><tr><th scope=\"row\">배당 수익</th><td>없음</td><td>있음</td><td>없음</td></tr></tbody></table></div><div class=\"ep-table-scroll\"><table><caption>표 2 · t+1 시점 경제 지표</caption><thead><tr><th scope=\"col\">경제 지표</th><th scope=\"col\">물가</th><th scope=\"col\">금리</th></tr></thead><tbody><tr><th scope=\"row\">예측되는 변화</th><td>㉠</td><td>㉡</td></tr></tbody></table></div></div>","options":["A는 B보다 수익성이 높은 금융 상품이다.","A와 달리 C는 예금자 보호 제도의 적용 대상이다.","만기가 있는 금융 상품과 만기가 없는 금융 상품의 구성 비율은 같다.","㉠이 상승이면 C에서 기대할 수 있는 수익의 실질 구매력이 증가할 것이다.","㉡이 하락이면 갑은 A의 구성 비율을 낮추고 B의 구성 비율을 높일 것이다."],"correct":4,"summary":"이자만 기대하는 A는 정기 예금, 배당이 있는 B는 주식, 이자와 시세 차익이 있는 C는 채권이에요. 원문의 재투자 상황에서는 금리 하락에 따라 예금 비중을 낮추는 판단을 해요.","steps":[{"title":"수익의 조합으로 상품을 찾어요","text":"이자만 있는 A는 정기 예금, 배당이 있는 B는 주식, 이자와 시세 차익이 있는 C는 채권이에요."},{"title":"만기와 물가의 영향을 확인해요","text":"만기가 있는 예금·채권은 50%+20%=70%, 만기가 없는 주식은 30%예요. 물가 상승은 같은 수익금의 실질 구매력을 낮춰요."},{"title":"재투자라는 조건을 적용해요","text":"t+1에 원금과 수익금을 새로 투자하는 상황이에요. 금리 하락은 새 예금의 이자 매력을 낮추므로, 이 문항의 수익 추구 조건에서는 예금 A를 줄이고 주식 B를 늘리는 방향이에요. 기존 정기 예금의 약정 금리를 바꾸는 상황은 아니에요."}],"reasons":["일반적으로 정기 예금보다 주식의 기대 수익성이 높아요.","원문에서 예금자 보호와 연결되는 상품은 정기 예금 A예요. 채권 C가 아니에요.","만기가 있는 A·C는 70%, 없는 B는 30%로 달라요.","물가가 오르면 같은 금액으로 살 수 있는 양이 줄어 실질 구매력이 감소해요.","재투자 시 새 예금의 이자 수익이 낮아질 것으로 예상하는 원문의 조건에 맞아요. 실제 주식 수익을 보장한다는 뜻은 아니에요."],"linked":false},{"id":"2026-2-06-20","year":2026,"grade":2,"month":6,"number":20,"modules":["capitalism"],"image":"assets/exams/2026-2-06-20.jpg","pdfPage":5,"topic":"산업 자본주의·산업 혁명","level":2,"points":1.5,"prompt":"다음 편지가 작성된 시기에 있었던 경제 상황으로 옳은 것은?","body":"<div class=\"ep-material\"><strong>데이비드 흄이 애덤 스미스에게 쓴 편지</strong><p>드디어 당신의 국부론이 출간되었구만. 나는 그 책을 읽으며 큰 즐거움을 얻었네. 책의 내용이 대중에게는 다소 어려울 수 있으나, 결국 최고의 평가를 받을 것이네. …(중략)… 금과 은을 쌓아두는 것이 국력이라고 주장하는 중상주의를 비판하고 그 오류를 명확하게 설명해 낸 점도 매우 훌륭하게 생각하네.</p></div>","options":["소수의 거대 기업이 시장을 독점하였다.","공장제 기계 공업의 발달로 대량 생산이 가능해졌다.","신자유주의를 바탕으로 시장의 자율성이 강화되었다.","두 차례의 석유 파동으로 스태그플레이션이 발생하였다.","미국에서 정부 주도로 테네시강 유역 개발 공사가 시작되었다."],"correct":1,"summary":"국부론 출간은 1776년으로 산업 혁명 시기와 연결돼요. 기계를 사용하는 공장제 생산이 발달하며 대량 생산이 가능해졌어요.","steps":[{"title":"편지의 시대를 확인해요","text":"애덤 스미스의 국부론은 중상주의를 비판하고 자유로운 경제 활동을 강조해요. 출간 연도는 1776년이에요."},{"title":"생산 방식의 변화를 연결해요","text":"산업 혁명으로 공장과 기계가 생산의 중심이 되면서 이전보다 많은 상품을 생산할 수 있었어요."},{"title":"독점·대공황·석유 파동을 구분해요","text":"거대 기업의 독점은 19세기 후반, 뉴딜 정책은 1930년대, 석유 파동과 신자유주의는 20세기 후반에 연결돼요."}],"reasons":["소수 거대 기업의 시장 독점은 19세기 후반 독점 자본주의의 특징이에요.","산업 혁명과 공장제 기계 공업의 발달을 설명하므로 자료의 시기에 맞아요.","신자유주의는 1970년대 이후의 경제 위기와 정부 개입의 한계를 배경으로 확산돼요.","두 차례 석유 파동은 1970년대의 일이에요.","테네시강 유역 개발은 대공황 이후 뉴딜 정책의 사례예요."],"linked":false},{"id":"2026-2-06-21","year":2026,"grade":2,"month":6,"number":21,"modules":["trade"],"image":"assets/exams/2026-2-06-21.jpg","pdfPage":5,"topic":"교환 비율과 무역 이익","level":3,"points":2,"prompt":"다음 자료에 대한 분석으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑국·을국은 동일한 노동량을 보유하고, 노동을 최대한 활용하여 X재와 Y재만 생산한다. 비교우위가 있는 재화만을 생산하고 거래 비용 없이 교역한다.</p><div class=\"ep-table-scroll\"><table><caption>재화별 생산에 필요한 노동자 수</caption><thead><tr><th scope=\"col\">국가</th><th scope=\"col\">X재 1단위</th><th scope=\"col\">Y재 1단위</th></tr></thead><tbody><tr><th scope=\"row\">갑국</th><td>5명</td><td>4명</td></tr><tr><th scope=\"row\">을국</th><td>2명</td><td>3명</td></tr></tbody></table></div></div>","options":["갑국은 X재 생산에 절대 우위를 가진다.","갑국의 Y재 최대 생산 가능량은 을국의 X재 최대 생산 가능량의 2배이다.","X재 1단위 생산의 기회비용은 을국이 갑국보다 크다.","Y재를 특화하여 수출하는 국가는 을국이다.","X재와 Y재를 1:1 비율로 교환하면 양국은 모두 이익을 얻는다."],"correct":4,"summary":"갑국은 Y재, 을국은 X재에 비교우위가 있어요. X재 1개를 Y재 1개와 바꾸는 비율은 양국의 X재 기회비용 사이에 있으므로 둘 다 이익을 얻어요.","steps":[{"title":"절대우위와 비교우위를 따로 구해요","text":"을국은 두 재화 모두 더 적은 노동이 필요해 절대우위가 있어요. 비교우위는 기회비용으로 다시 판단해요.","formula":"X재 1개 기회비용: 갑국 Y재 5/4개, 을국 Y재 2/3개\nY재 1개 기회비용: 갑국 X재 4/5개, 을국 X재 3/2개"},{"title":"특화 방향을 정해요","text":"갑국은 Y재 기회비용이 낮고, 을국은 X재 기회비용이 낮아요. 따라서 갑국은 Y재, 을국은 X재를 수출해요."},{"title":"교환 비율이 양쪽에 유리한지 확인해요","text":"을국은 X재를 만들어 국내에서 Y재 2/3개를 포기하지만 교환하면 Y재 1개를 얻어요. 갑국은 직접 X재를 만들 때 Y재 5/4개를 포기하지만 교환에는 Y재 1개만 내요.","formula":"2/3 < 1 < 5/4 → 양국 모두 이익"}],"reasons":["X재 1개에 필요한 노동은 갑국 5명, 을국 2명으로 을국이 절대우위예요.","노동량이 같으면 갑국 Y재 최대량은 노동량/4, 을국 X재는 노동량/2예요. 비율은 2배가 아니라 1/2배예요.","X재 기회비용은 갑국 5/4, 을국 2/3으로 갑국이 더 커요.","Y재를 특화·수출하는 나라는 갑국이에요.","1:1 비율은 두 나라 기회비용 사이에 있어 두 나라 모두 직접 생산할 때보다 유리해요."],"linked":false},{"id":"2026-2-06-23","year":2026,"grade":2,"month":6,"number":23,"modules":["cost","ripple"],"image":"assets/exams/2026-2-06-23.jpg","pdfPage":6,"topic":"기간별 비용·보조금·외부 효과","level":3,"points":2.5,"prompt":"밑줄 친 ㉠~㉣에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>○○국 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">정부</u>는 탄소 배출량을 감축하고 재생에너지 사용을 장려하기 위해 가정용 태양광 발전기를 설치할 경우 <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">설치 비용의 50%를 보조금으로 지급하는 정책</u>을 시행하고 있다. 갑은 편익과 기회비용만을 고려하여 현재 거주하고 있는 집에 <span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">태양광 발전기</u>를 설치할지의 여부를 선택하려고 한다. 갑이 설치를 선택할 경우 <span class=\"ep-reference\">㉣</span><u class=\"ep-underlined\" data-ref=\"㉣\">설치 비용 2,000달러 중 정부 보조금을 제외한 금액</u>과 매월 20달러의 유지·보수 비용을 부담해야 하며, 전기 요금 절감으로 매월 60달러의 편익을 얻는다. 단, 설치한 태양광 발전기는 이전 설치 및 판매가 불가능하다.</p></div>","options":["㉠은 이윤 극대화를 추구하는 경제 주체이다.","㉡은 외부 불경제를 해결하기 위한 정책이다.","㉣은 ㉢ 설치에 따른 암묵적 비용이다.","갑이 ㉢을 설치하지 않을 경우 기회비용이 발생하지 않는다.","갑이 2년 이내에 이사할 예정이라면 ㉢을 설치하지 않는 것이 합리적이다."],"correct":4,"summary":"2년은 24개월이에요. 24개월 동안 얻는 편익은 1,440달러, 내는 비용은 1,480달러로, 2년 이내에는 비용이 더 커요.","steps":[{"title":"보조금을 빼고 실제 설치비를 구해요","text":"정부가 절반을 지원하므로 갑이 실제로 내는 초기 비용은 절반이에요.","formula":"2,000 × (1 − 0.5) = 1,000달러"},{"title":"비교 기간을 24개월로 맞춰요","text":"한 번 내는 설치비와 매월 내는 유지비를 함께 고려해야 해요. 편익도 같은 24개월로 합해요.","formula":"24개월 편익 = 60 × 24 = 1,440달러\n24개월 비용 = 1,000 + 20 × 24 = 1,480달러"},{"title":"2년 이내라는 조건을 판단해요","text":"24개월에도 편익이 40달러 적어요. 매월 편익에서 유지비를 뺀 값이 40달러이므로 더 짧게 사용하면 초기 비용을 회수하기 더 어려워요.","formula":"24개월의 차이 = 1,440 − 1,480 = −40달러"}],"reasons":["이윤 극대화를 주된 목적으로 하는 주체는 기업이에요. 정부는 공익과 경제 문제 해결 등을 위해 정책을 시행해요.","이 문항은 태양광 보급의 긍정적 외부 효과를 늘리기 위한 보조금으로 구분해요. 원문의 외부 불경제는 부정적 외부 효과를 뜻해요.","설치하면서 실제로 지출하는 비용이므로 명시적 비용이에요. 보조금을 뺀 실제 부담과 원래 설치비도 구분해요.","설치하지 않는 선택에도 설치를 통해 얻을 수 있었던 가치를 포기하는 측면이 있어요. 기회비용이 전혀 없다고 단정할 수 없어요.","2년간 편익 1,440달러보다 비용 1,480달러가 커요. 이전 설치·판매도 불가능하므로 주어진 조건에서는 설치하지 않는 쪽이 합리적이에요."],"linked":true},{"id":"2026-2-09-06","year":2026,"grade":2,"month":9,"number":6,"modules":["ripple"],"image":"assets/exams/2026-2-09-06.jpg","pdfPage":2,"topic":"정부·기업·시민 단체 구분","level":1,"points":1.5,"prompt":"(가)~(다)에 해당하는 행위 주체로 옳은 것은?","body":"<div class=\"ep-passage\"><p>기후 변화 대응을 위해 다양한 행위 주체들이 탄소 절감에 동참하고 있다.</p><p><span class=\"ep-blank-label\">(가)</span> 온실가스 배출 규제를 강화하고 조세 감면 등의 재정 지원을 병행하며 녹색 성장의 제도적 기반을 마련한다.</p><p><span class=\"ep-blank-label\">(나)</span> 생산 활동의 주체로, 사용 전력의 100%를 재생 에너지로 전환하려는 RE100에 자율적으로 참여한다.</p><p><span class=\"ep-blank-label\">(다)</span> 정책이 제대로 이행되는지 감시·비판하며 저탄소 생활 양식 확산을 위한 캠페인을 전개한다.</p></div>","options":["정부 / 기업 / 시민 단체","정부 / 시민 단체 / 기업","기업 / 정부 / 시민 단체","기업 / 시민 단체 / 정부","시민 단체 / 기업 / 정부"],"correct":0,"summary":"규제·재정 지원은 정부, 생산과 경영은 기업, 감시·캠페인은 시민 단체의 역할이에요. 순서대로 정부·기업·시민 단체예요.","steps":[{"title":"정책 수단을 사용하는 주체를 찾아요","text":"배출 규제와 조세 감면은 정부의 제도적 수단이므로 (가)는 정부예요."},{"title":"생산과 캠페인을 구분해요","text":"생산 활동과 경영 계획은 기업의 역할이에요. 정부 정책 감시·비판과 시민 캠페인은 시민 단체와 연결돼요."},{"title":"자료의 순서대로 적어요","text":"(가) 정부 → (나) 기업 → (다) 시민 단체이므로 ①이에요."}],"reasons":["세 주체가 모두 자료의 역할에 맞게 연결되어 있어요.","생산 활동의 주체 (나)는 기업, 감시·캠페인의 (다)는 시민 단체예요.","규제·조세 감면을 하는 (가)는 정부, 생산하는 (나)는 기업이에요.","(가)는 정부, (나)는 기업, (다)는 시민 단체로 고쳐야 해요.","제도적 기반을 마련하는 (가)는 정부이고 감시·캠페인의 (다)는 시민 단체예요."],"linked":true,"choiceColumns":["(가)","(나)","(다)"]},{"id":"2026-2-09-11","year":2026,"grade":2,"month":9,"number":11,"modules":["capitalism"],"image":"assets/exams/2026-2-09-11.jpg","pdfPage":3,"topic":"경제 위기와 자본주의의 변화","level":2,"points":2,"prompt":"(가), (나)에 대한 설명으로 옳은 것은?","body":"<p>(가), (나)는 각각 수정 자본주의와 신자유주의 중 하나이다.</p><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"book\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-2-09-11-book\" data-src=\"assets/exams/materials/2026-2-09-11-book.png\" data-title=\"경제 위기 극복을 위한 대응\" data-alt=\"경제 위기 극복을 위한 대응. 왼쪽 루스벨트 대통령과 오른쪽 레이건 대통령에 관한 책 형태의 자료. 자세한 본문은 자료 글로 읽기에서도 확인할 수 있다.\" aria-label=\"경제 위기 극복을 위한 대응 크게 보기\"><img src=\"assets/exams/materials/2026-2-09-11-book.png\" width=\"1231\" height=\"797\" alt=\"경제 위기 극복을 위한 대응. 왼쪽 루스벨트 대통령과 오른쪽 레이건 대통령에 관한 책 형태의 자료. 자세한 본문은 자료 글로 읽기에서도 확인할 수 있다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 경제 위기 극복을 위한 대응</figcaption></figure><details class=\"ep-material-transcript\"><summary>자료 글로 읽기</summary><div class=\"ep-material\"><strong>프랭클린 루스벨트 대통령</strong><p>20세기 들어 독과점 기업의 과잉 생산과 유효 수요 부족 문제가 발생하였다. 그 결과 1929년 대공황이 일어나 수많은 기업과 은행이 파산하고 실업률이 급증하였다. 이러한 경제 위기를 극복하기 위해 루스벨트 대통령은 <strong>(가)</strong>에 입각한 뉴딜 정책을 실시하였다.</p></div><div class=\"ep-material\"><strong>로널드 레이건 대통령</strong><p>1970년대에 일어난 두 차례의 석유 파동으로 인해 경기 침체와 물가 상승이 동시에 발생하였고, 이는 세계적 불황으로 이어졌다. 이러한 경제 위기 상황 속에서 레이건 대통령은 정부 역할의 축소를 지향하는 <strong>(나)</strong>에 입각한 정책을 실시하였다.</p></div></details>","options":["(가)는 정부가 시장에 개입하여 나타난 문제점을 해결하기 위해 등장하였다.","(나)는 공기업의 민영화를 지지한다.","(가)와 달리 (나)는 케인스의 이론에 기반하였다.","(나)와 달리 (가)는 정부의 규제 완화를 주장한다.","(가)와 (나) 모두 사유 재산 제도를 부정한다."],"correct":1,"summary":"(가)는 수정 자본주의, (나)는 신자유주의예요. 신자유주의는 정부 역할을 줄이는 공기업 민영화 등을 지지해요.","steps":[{"title":"경제 위기와 대응을 한 쌍으로 읽어요","text":"대공황에 대한 뉴딜 정책은 수정 자본주의예요. 석유 파동 이후 정부 역할 축소는 신자유주의예요."},{"title":"민영화의 뜻을 연결해요","text":"공기업을 민간 중심으로 운영하도록 바꾸는 민영화는 정부의 직접적인 경제 활동을 줄이는 방향이에요."},{"title":"공통점도 확인해요","text":"두 입장은 정부 역할의 크기에서 다르지만 모두 자본주의로, 사유 재산 제도를 바탕으로 해요."}],"reasons":["정부 개입의 문제를 해결하려는 것은 신자유주의의 등장 배경이에요. 수정 자본주의는 시장 실패 해결과 연결돼요.","정부 역할 축소를 강조하는 신자유주의는 공기업 민영화를 지지해요.","케인스의 이론에 기반한 것은 (가) 수정 자본주의예요.","규제 완화는 (나) 신자유주의와 연결돼요.","둘 다 자본주의이므로 사유 재산 제도를 부정하지 않아요."],"linked":false},{"id":"2026-2-09-17","year":2026,"grade":2,"month":9,"number":17,"modules":["cost"],"image":"assets/exams/2026-2-09-17.jpg","pdfPage":4,"topic":"구매 혜택·기회비용","level":3,"points":2.5,"prompt":"다음 자료에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>표는 마트에서 판매하는 상품 A·B의 구매 혜택, 개당 가격, 갑이 소비하여 얻는 편익이다.</p><div class=\"ep-table-scroll\"><table><caption>가격·편익 단위: 원</caption><thead><tr><th scope=\"col\">구분</th><th scope=\"col\">상품 A</th><th scope=\"col\">상품 B</th></tr></thead><tbody><tr><th scope=\"row\">구매 혜택</th><td>1개 구매 시 1개 무료</td><td>2개 구매 시 1개 무료</td></tr><tr><th scope=\"row\">개당 가격</th><td>3,000</td><td>1,500</td></tr><tr><th scope=\"row\">1개 소비 시 편익</th><td>4,000</td><td>2,500</td></tr><tr><th scope=\"row\">2개 소비 시 편익</th><td>7,000</td><td>4,000</td></tr><tr><th scope=\"row\">3개 소비 시 편익</th><td>해당 없음</td><td>5,000</td></tr></tbody></table></div><div class=\"ep-material\"><strong>선택할 두 가지 안</strong><p><strong>1안:</strong> A 1개를 구매해 2개 소비<br><strong>2안:</strong> B 2개를 구매해 3개 소비</p></div><p>갑은 편익과 기회비용만 고려해 합리적으로 선택한다. 구매하여 얻은 상품은 전량 소비하며, 다른 조건은 고려하지 않는다.</p></div>","options":["갑은 2안을 선택하는 것이 합리적이다.","편익은 1안을 선택할 때가 2안을 선택할 때보다 1,500원 더 크다.","기회비용은 1안을 선택할 때가 2안을 선택할 때보다 2,000원 더 작다.","암묵적 비용은 1안을 선택할 때가 2안을 선택할 때보다 1,000원 더 작다.","명시적 비용은 1안을 선택할 때가 2안을 선택할 때보다 1,500원 더 크다."],"correct":2,"summary":"무료 증정품에는 가격을 다시 내지 않아요. 두 안의 지출은 모두 3,000원이고, 기회비용은 각각 5,000원과 7,000원이에요.","steps":[{"title":"구매 개수와 소비 개수를 구분해요","text":"1안은 A 1개 값으로 2개를 먹고, 2안은 B 2개 값으로 3개를 먹어요. 편익은 실제 소비 개수에 해당하는 행을 읽어요.","formula":"1안: 지출 3,000원 / 편익 7,000원\n2안: 지출 1,500 × 2 = 3,000원 / 편익 5,000원"},{"title":"포기한 안의 이익을 구해요","text":"1안을 고르면 2안의 편익−가격을, 2안을 고르면 1안의 편익−가격을 포기해요.","formula":"1안의 암묵적 비용 = 5,000 − 3,000 = 2,000원\n2안의 암묵적 비용 = 7,000 − 3,000 = 4,000원"},{"title":"기회비용을 비교해요","text":"실제 지출과 포기한 이익을 더해요. 1안의 기회비용이 2,000원 더 작아요.","formula":"1안: 3,000 + 2,000 = 5,000원\n2안: 3,000 + 4,000 = 7,000원"}],"reasons":["순편익은 1안 2,000원, 2안 −2,000원이에요. 1안이 더 합리적이에요.","편익 차이는 7,000 − 5,000 = 2,000원이에요.","기회비용은 1안 5,000원, 2안 7,000원으로 1안이 2,000원 작아요.","암묵적 비용의 차이는 4,000 − 2,000 = 2,000원이에요.","두 안 모두 실제 지출이 3,000원으로 같아요."],"linked":false},{"id":"2026-2-09-18","year":2026,"grade":2,"month":9,"number":18,"modules":["finance"],"image":"assets/exams/2026-2-09-18.jpg","pdfPage":5,"topic":"금융 상품 식별·안전성","level":2,"points":1.5,"prompt":"다음 자료에 대한 분석으로 옳은 것은?","body":"<div class=\"ep-passage\"><div class=\"ep-material\"><strong>경제 뉴스</strong><p>고용 지표가 개선되고 물가가 지속적으로 상승하자 중앙은행은 기준 금리를 인상하기로 했다. 정부·공공 기관 등이 빌린 돈을 갚기로 약속하고 발행한 증서인 A의 수요가 감소할 것으로 예상된다.</p></div><div class=\"ep-material\"><strong>투자자들의 판단</strong><p>한 투자자는 회사가 자금을 조달받는 대가로 소유권 일부를 주는 증서 B의 투자 비중을 줄이려 한다. 다른 투자자는 은행에서 새로 출시한 C의 수익성이 높아질 것으로 예상하여 C에 투자하려 한다.</p></div><p>A~C는 일반적인 특징을 가진 예금·주식·채권 중 하나이며, 다른 조건은 고려하지 않는다.</p></div>","options":["A는 B보다 안전성이 높다.","A와 달리 B는 시세 차익을 기대할 수 있다.","B와 달리 C는 배당 수익을 기대할 수 있다.","C와 달리 A는 이자 수익을 기대할 수 있다.","C와 달리 B는 예금자 보호 제도의 적용을 받는다."],"correct":0,"summary":"A는 돈을 빌려준 관계를 나타내는 채권, B는 기업 소유권의 일부인 주식, C는 예금이에요. 일반적인 특징을 비교하면 채권은 주식보다 안전성이 높아요.","steps":[{"title":"상품을 설명하는 핵심어를 읽어요","text":"갚기로 약속한 증서는 채권, 소유권의 일부는 주식, 은행에서 출시하는 예금 상품은 예금이에요.","formula":"A = 채권 / B = 주식 / C = 예금"},{"title":"수익을 구별해요","text":"주식은 배당·시세 차익, 채권은 이자·시세 차익, 예금은 이자로 구분해요."},{"title":"일반적인 안전성 비교를 적용해요","text":"원문은 일반적인 상품 특징을 묻고 있어요. 채권은 약정에 따른 원리금 지급과 연결되어 주식보다 일반적으로 안전성이 높지만, 모든 채권이 무위험이라는 뜻은 아니에요."}],"reasons":["일반적인 상품 특징에서는 채권 A가 주식 B보다 안전성이 높아요.","A 채권도 B 주식도 시세 차익을 기대할 수 있어요.","배당은 B 주식과 연결되며 C 예금의 수익은 이자예요.","A 채권과 C 예금 모두 이자 수익을 기대할 수 있어요.","원문의 예금자 보호와 연결되는 것은 C 예금이에요. B 주식은 해당하지 않아요."],"linked":false},{"id":"2026-2-09-24","year":2026,"grade":2,"month":9,"number":24,"modules":["trade"],"image":"assets/exams/2026-2-09-24.jpg","pdfPage":6,"topic":"생산 가능 곡선·교역 후 소비","level":3,"points":2.5,"prompt":"다음 자료에 대한 분석으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑국·을국은 X재와 Y재만 생산한다. 비교우위가 있는 재화만 생산하여 <strong>X재 2개당 Y재 1개</strong>로 교환하며, X재 수출국은 <strong>X재 20개를 수출</strong>했다. 양국은 같은 노동량을 모두 생산에 투입하고, 양국 간 거래 비용은 없으며 생산된 재화는 모두 소비한다.</p><div class=\"ep-visual-pair\"><figure class=\"ep-source-figure ep-source-original\" data-material-kind=\"ppf\"><button type=\"button\" class=\"ep-material-open\" data-ep=\"material-open\" data-material-id=\"2026-2-09-24-ppf\" data-src=\"assets/exams/materials/2026-2-09-24-ppf.png\" data-title=\"각국의 생산 가능 곡선\" data-alt=\"각국의 생산 가능 곡선. 갑국 실선의 절편은 X재 40개·Y재 30개, 을국 파선의 절편은 X재 50개·Y재 20개이다. 가로축은 X재 개수, 세로축은 Y재 개수이며 10개 간격의 눈금이 표시되어 있다.\" aria-label=\"각국의 생산 가능 곡선 크게 보기\"><img src=\"assets/exams/materials/2026-2-09-24-ppf.png\" width=\"578\" height=\"517\" alt=\"각국의 생산 가능 곡선. 갑국 실선의 절편은 X재 40개·Y재 30개, 을국 파선의 절편은 X재 50개·Y재 20개이다. 가로축은 X재 개수, 세로축은 Y재 개수이며 10개 간격의 눈금이 표시되어 있다.\" loading=\"lazy\"><span>자료 확대 ↗</span></button><figcaption>출제 원문 · 각국의 생산 가능 곡선</figcaption></figure><div class=\"ep-table-scroll\"><table><caption>교역 전 소비량 · 단위: 개</caption><thead><tr><th scope=\"col\">구분</th><th scope=\"col\">갑국</th><th scope=\"col\">을국</th></tr></thead><tbody><tr><th scope=\"row\">X재</th><td>20</td><td>30</td></tr><tr><th scope=\"row\">Y재</th><td>15</td><td>8</td></tr></tbody></table></div></div><p class=\"ep-definition-note\">* 생산 가능 곡선: 한 국가에서 최대한으로 생산할 수 있는 상품 조합을 나타내는 곡선</p></div>","options":["갑국은 X재 생산에 절대 우위와 비교 우위를 모두 가진다.","갑국의 Y재 1개 생산의 기회비용은 X재 0.75개이다.","을국의 X재 1개 생산의 기회비용은 Y재 2.5개이다.","교역 후 양국의 X재 소비량 합계는 40개이다.","교역 후 갑국은 Y재 5개, 을국은 Y재 2개를 추가로 소비할 수 있다."],"correct":4,"summary":"갑국은 Y재 30개, 을국은 X재 50개에 특화해요. X재 20개와 Y재 10개를 교환하면 두 나라의 Y재 소비가 각각 5개와 2개 늘어요.","steps":[{"title":"절편을 최대 생산량으로 읽어요","text":"갑국은 X재 최대 40개 또는 Y재 30개, 을국은 X재 최대 50개 또는 Y재 20개를 생산해요.","formula":"X재 기회비용: 갑국 Y재 30/40=3/4, 을국 Y재 20/50=2/5\nY재 기회비용: 갑국 X재 4/3, 을국 X재 5/2"},{"title":"특화 후 교환량을 적용해요","text":"X재 기회비용이 낮은 을국은 X재 50개, 갑국은 Y재 30개를 생산해요. 을국이 X재 20개를 수출하면 2:1 비율에 따라 Y재 10개를 받아요.","formula":"교역 후 갑국: X재 20개, Y재 30−10=20개\n교역 후 을국: X재 50−20=30개, Y재 10개"},{"title":"교역 전과 같은 재화를 비교해요","text":"X재 소비는 각국 20·30개로 이전과 같고, Y재 소비가 늘었어요.","formula":"갑국 Y재 증가 = 20−15 = 5개\n을국 Y재 증가 = 10−8 = 2개"}],"reasons":["X재 최대 생산량과 기회비용 모두 을국이 유리해요.","갑국 Y재 1개의 기회비용은 X재 4/3개예요. 0.75는 갑국 X재의 기회비용에 대응해요.","을국 X재 1개의 기회비용은 Y재 2/5개예요. 2.5는 Y재의 기회비용에 대응해요.","교역 후 X재 소비 합계는 20+30=50개예요.","교역 후 Y재는 갑국 20개, 을국 10개로 교역 전보다 각각 5개·2개 늘어요."],"linked":false},{"id":"2026-2-10-11","year":2026,"grade":2,"month":10,"number":11,"modules":["capitalism"],"image":"assets/exams/2026-2-10-11.jpg","pdfPage":3,"topic":"석유 파동·정부 실패","level":2,"points":2,"prompt":"다음 경제 상황과 경제학자 갑의 주장에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>1973년 아랍 산유국들은 이스라엘 지원국에 대응하여 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">석유 생산량을 감축하고 특정 국가에 대한 석유 수출을 제한</u>하였다. 국제 유가는 몇 달 만에 약 4배 상승했다. 1978년 이후에도 주요 산유국의 정치적 불안으로 석유 공급 우려가 커지며 유가가 급등했다. 두 차례의 유가 급등은 <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">스태그플레이션</u>을 초래했다.</p><div class=\"ep-material\"><strong>경제학자 갑</strong><p>각국 정부의 정책은 뚜렷한 성과를 내지 못하였습니다. 이는 <span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">정부의 적극적인 시장 개입을 통해 경제 문제를 해결하려 했던 자본주의</u>의 한계가 드러난 사례입니다. 시장에 대한 정부의 인위적 통제는 자원의 효율적 배분을 왜곡합니다. 정부는 지나친 개입을 줄이고 민간의 자유로운 경제 활동을 보장해야 합니다.</p></div></div>","options":["㉠은 수입한 자원을 자국의 정치적·경제적 이익을 위해 전략적 무기로 활용한 사례이다.","㉡은 경기 침체와 물가 상승이 동시에 발생하는 현상이다.","㉢은 정부 실패를 해결하기 위해 등장하였다.","갑은 공기업 민영화와 기업 규제 완화 정책에 부정적일 것이다.","갑은 경제 문제 해결의 기준으로 형평성을 효율성보다 강조할 것이다."],"correct":1,"summary":"스태그플레이션은 경기 침체와 물가 상승이 함께 나타나는 현상이에요. 갑은 정부 개입의 한계를 지적하는 신자유주의 입장이에요.","steps":[{"title":"위기의 이름을 정확히 이해해요","text":"유가 상승으로 생산 비용이 커지는 가운데 경제가 침체할 수 있어요. 침체와 물가 상승이 겹친 상태가 스태그플레이션이에요."},{"title":"비판 대상과 주장하는 입장을 나눠요","text":"㉢은 정부 개입을 강조했던 수정 자본주의이고, 갑은 그 한계를 비판하며 신자유주의를 주장해요."},{"title":"정책의 방향을 연결해요","text":"갑은 민영화·규제 완화를 지지하는 쪽이에요. 또한 시장의 효율적 자원 배분을 강조해요."}],"reasons":["자료는 석유를 보유한 산유국이 생산·수출을 조절한 사례예요. 수입한 자원을 활용했다는 표현이 틀려요.","경기 침체와 물가 상승이 동시에 발생한다는 스태그플레이션의 정의에 맞아요.","㉢ 수정 자본주의는 시장 실패를 해결하는 과정에서 등장했어요.","정부 역할 축소를 강조하는 갑은 민영화와 규제 완화를 지지할 것이에요.","갑은 효율적 자원 배분을 강조하므로 효율성을 형평성보다 강조하는 입장이에요."],"linked":false},{"id":"2026-2-10-16","year":2026,"grade":2,"month":10,"number":16,"modules":["trade"],"image":"assets/exams/2026-2-10-16.jpg","pdfPage":4,"topic":"특화·교환·소비량 비교","level":3,"points":2.5,"prompt":"다음 자료에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑국·을국은 X재와 Y재만 생산해 전량 소비한다. 양국의 생산 요소는 동일한 양의 노동뿐이고 각 재화의 기회비용은 일정하며 교환 비용은 없다.</p><div class=\"ep-table-scroll\"><table><caption>생산에 필요한 노동량 · 단위: 명</caption><thead><tr><th scope=\"col\">국가</th><th scope=\"col\">X재 1단위</th><th scope=\"col\">Y재 1단위</th></tr></thead><tbody><tr><th scope=\"row\">갑국</th><td>4</td><td>5</td></tr><tr><th scope=\"row\">을국</th><td>3</td><td>2</td></tr></tbody></table></div><p>무역 전 갑국은 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">전체 노동량</u>으로 X재 10단위와 Y재 4단위를 생산했다. 이후 비교우위 재화만 특화한 뒤 <strong>X재 5단위와 Y재 5단위</strong>를 교환하여 갑국은 무역 전보다 <strong>(가)</strong>만큼 이익을 얻었다.</p></div>","options":["㉠은 38명이다.","(가)에는 Y재 1단위가 들어갈 수 있다.","최대로 생산할 수 있는 X재의 양은 갑국이 을국보다 많다.","갑국은 Y재 생산에, 을국은 X재 생산에 비교 우위를 가진다.","양국 간 무역이 발생하는 이유는 절대 우위만으로 설명할 수 있다."],"correct":1,"summary":"갑국의 노동량은 60명이고 X재 15단위에 특화할 수 있어요. X재 5단위를 주고 Y재 5단위를 받으면 X재 10·Y재 5를 소비해, 무역 전보다 Y재가 1단위 늘어요.","steps":[{"title":"무역 전 사용한 전체 노동량을 구해요","text":"갑국 X재 10단위에는 40명분, Y재 4단위에는 20명분의 노동이 필요해요.","formula":"전체 노동량 = 10×4 + 4×5 = 60명"},{"title":"비교우위와 특화 생산량을 구해요","text":"X재 기회비용은 갑국 4/5, 을국 3/2로 갑국이 작아요. 갑국은 X재를 특화해요.","formula":"갑국 X재 특화 생산량 = 60 ÷ 4 = 15단위"},{"title":"내보낸 양을 빼고 받은 양을 더해요","text":"갑국은 X재 15 중 5를 수출하고 Y재 5를 수입해요. 무역 전 X재 10·Y재 4와 비교하면 X재는 같고 Y재가 1 늘어요.","formula":"교역 후 소비 = X재 10단위 + Y재 5단위\n추가 소비 = Y재 5−4 = 1단위"}],"reasons":["전체 노동량은 10×4+4×5=60명이에요.","교역 후 갑국 소비는 X재 10·Y재 5로, Y재가 무역 전의 4보다 1 늘어요.","같은 노동량 60명으로 X재 최대 생산량은 갑국 15, 을국 20단위예요.","갑국은 X재, 을국은 Y재에 비교우위가 있어요.","을국이 두 재화 모두 절대우위인데도 무역해요. 무역의 이유는 비교우위로 설명할 수 있어요."],"linked":false},{"id":"2026-2-10-19","year":2026,"grade":2,"month":10,"number":19,"modules":["cost","ripple"],"image":"assets/exams/2026-2-10-19.jpg","pdfPage":5,"topic":"매몰 비용·긍정적 외부 효과","level":3,"points":2.5,"prompt":"다음 자료에 대한 설명으로 옳은 것은?","body":"<div class=\"ep-passage\"><p>갑은 주말 여행 상품을 예약하며 <span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">20만 원</u>을 지불했다. 여행 당일 전통문화 공연을 알게 된 갑은 환불이 불가능하지만 <span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">여행을 포기</u>하고, 판소리·사물놀이 공연 중 하나를 합리적으로 선택하려 한다.</p><div class=\"ep-table-scroll\"><table><caption>단위: 만 원</caption><thead><tr><th scope=\"col\">구분</th><th scope=\"col\">판소리 공연</th><th scope=\"col\">사물놀이 공연</th></tr></thead><tbody><tr><th scope=\"row\">편익</th><td>33</td><td>35</td></tr><tr><th scope=\"row\">암묵적 비용</th><td>7</td><td>8</td></tr></tbody></table></div><p>공연 관람은 관람객의 편익 외에 전통문화의 계승·대중화라는 사회적 편익을 추가로 발생시킨다. 관람객은 그 대가를 받을 수 없어 <span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">외부 효과</u>가 발생한다. 정부는 관람이 사회적으로 적정한 수준만큼 이루어지도록 <span class=\"ep-reference\">㉣</span><u class=\"ep-underlined\" data-ref=\"㉣\">정책</u>을 시행하려 한다.</p></div>","options":["판소리 공연 관람 선택에 따른 명시적 비용은 25만 원이다.","사물놀이 공연 관람 선택에 따른 순편익은 양(+)의 값이다.","㉠은 ㉡의 선택에 따른 암묵적 비용이다.","㉢으로 인해 전통문화 공연 관람은 사회적으로 적정한 수준보다 많이 이루어진다.","㉣의 사례로 전통문화 공연 관람객에 대한 세금 부과를 들 수 있다."],"correct":0,"summary":"판소리를 포기할 때의 이익 8만 원이 사물놀이의 암묵적 비용이에요. 따라서 판소리 가격은 편익 33만 원에서 8만 원을 뺀 25만 원이에요.","steps":[{"title":"이미 돌려받을 수 없는 돈을 제외해요","text":"여행비 20만 원은 어떤 공연을 고르더라도 회수할 수 없어요. 앞으로의 선택을 비교할 때 제외하는 매몰 비용이에요."},{"title":"상대 대안의 암묵적 비용에서 가격을 구해요","text":"사물놀이를 고르면 판소리에서 얻었을 이익을 포기해요. 그 값이 8만 원이므로 판소리 편익에서 빼면 실제 지출액이 나와요.","formula":"판소리 명시적 비용 = 33 − 8 = 25만 원\n사물놀이 명시적 비용 = 35 − 7 = 28만 원"},{"title":"두 순편익과 외부 효과를 확인해요","text":"판소리의 순편익은 양수이고 사물놀이는 음수예요. 문화 계승이라는 제3자의 이익은 긍정적 외부 효과로, 관람이 적게 이루어질 수 있어 보조금 등이 적합해요.","formula":"판소리: 33 − (25 + 7) = 1만 원\n사물놀이: 35 − (28 + 8) = −1만 원"}],"reasons":["사물놀이의 암묵적 비용 8만 원은 포기한 판소리의 편익−가격이에요. 판소리 가격은 33 − 8 = 25만 원이에요.","사물놀이의 순편익은 35 − (28 + 8) = −1만 원으로 음수예요.","환불 불가능한 여행비 20만 원은 이미 지출해 회수할 수 없는 매몰 비용이에요.","긍정적 외부 효과는 사회적으로 필요한 수준보다 적게 이루어지는 문제와 연결돼요.","세금은 관람을 줄이는 방향이에요. 보조금·세금 감면 등 관람을 늘리는 유인을 검토해야 해요."],"linked":true},{"id":"2026-2-10-22","year":2026,"grade":2,"month":10,"number":22,"modules":["finance"],"image":"assets/exams/2026-2-10-22.jpg","pdfPage":6,"topic":"자산 구성 비율·금리","level":2,"points":2,"prompt":"다음 형성 평가 결과에 대한 옳은 설명만을 보기에서 고른 것은?","body":"<div class=\"ep-passage\"><p>아래 형성 평가의 점수는 3점 만점에 3점이다. 표는 갑의 모든 금융 자산 구성 비율이다.</p><div class=\"ep-table-scroll\"><table><thead><tr><th scope=\"col\">구분</th><th scope=\"col\"><span class=\"ep-reference\">㉠</span><u class=\"ep-underlined\" data-ref=\"㉠\">정기 예금</u></th><th scope=\"col\"><span class=\"ep-reference\">㉡</span><u class=\"ep-underlined\" data-ref=\"㉡\">채권</u></th><th scope=\"col\"><span class=\"ep-reference\">㉢</span><u class=\"ep-underlined\" data-ref=\"㉢\">주식</u></th></tr></thead><tbody><tr><th scope=\"row\">비율</th><td>60%</td><td>30%</td><td>10%</td></tr></tbody></table></div><div class=\"ep-material\"><strong>형성 평가의 빈칸</strong><p>1. 시세 차익을 기대할 수 있는 금융 자산의 총비율(%): <strong>(가)</strong><br>2. 이자 수익을 기대할 수 있는 금융 자산의 총비율(%): <strong>(나)</strong><br>3. 금리 상승 때 금융 자산 비율을 합리적으로 조정하는 방향 한 가지: <strong>(다)</strong></p></div></div><fieldset class=\"ep-statements\" aria-label=\"보기\"><legend>〈보 기〉</legend><p>ㄱ. ㉠과 달리 ㉡은 만기가 있다.</p><p>ㄴ. 일반적으로 ㉢은 ㉡보다 안전성이 낮다.</p><p>ㄷ. (가)는 (나)보다 작다.</p><p>ㄹ. (다)에는 주식의 투자 비율을 높인다가 들어갈 수 있다.</p></fieldset>","options":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"correct":2,"summary":"시세 차익을 기대하는 채권·주식은 40%, 이자를 기대하는 예금·채권은 90%예요. 주식의 안전성이 채권보다 낮다는 ㄴ과, 40%가 90%보다 작다는 ㄷ이 맞아요.","steps":[{"title":"만기가 있는 상품을 구분해요","text":"정기 예금과 채권은 모두 만기가 있어요. 주식에는 정해진 만기가 없어요."},{"title":"해당하는 상품 비율을 더해요","text":"시세 차익은 채권·주식, 이자는 정기 예금·채권에 연결돼요.","formula":"(가) = 30 + 10 = 40%\n(나) = 60 + 30 = 90%"},{"title":"금리 상승 시 원문의 판단 방향을 확인해요","text":"금리 상승은 새 예금의 이자 매력을 높이고 주식 투자 비중을 낮추는 방향으로 설명돼요. 원문의 가정 아래 정기 예금 비중을 높이는 답이 가능해요."}],"reasons":["ㄴ은 맞지만 ㄱ은 틀려요. 정기 예금과 채권 모두 만기가 있어요.","ㄷ은 맞지만 ㄱ은 틀려요. 채권만 만기가 있는 것이 아니에요.","ㄴ의 일반적 안전성 비교와 ㄷ의 40% < 90%가 모두 맞아요.","ㄴ은 맞지만 ㄹ은 원문의 금리 상승 상황에 맞지 않아요.","ㄷ은 맞지만 ㄹ은 정기 예금 비중을 높이는 방향으로 고쳐야 해요."],"linked":false}]};function freeze(x){if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;}window.GalpiExamData=freeze(data);})();
